int searchBitonic(vector<int>& arr, int target) {
    int peak = findBitonicPeak(arr);
    int ans = binarySearchIncreasing(
        arr, 0, peak, target);
    if (ans != -1)
        return ans;
    return binarySearchDecreasing(
        arr, peak + 1, arr.size() - 1, target);
}

bool canShip(
    vector<int>& weights,
    int days,
    long long cap) {
    int usedDays = 1;
    long long curr = 0;
    for (int w : weights) {
        if (curr + w > cap) {
            usedDays++;
            curr = 0;
        }
        curr += w;
    }
    return usedDays <= days;
}
long long shipWithinDays(
    vector<int>& weights,
    int days) {
    long long l = *max_element(
        weights.begin(),
        weights.end()
    );
    long long r =
        accumulate(
            weights.begin(),
            weights.end(),
            0LL
        );
    while (l < r) {
        long long mid =
            l + (r - l) / 2;
        if (canShip(weights, days, mid))
            r = mid;
        else
            l = mid + 1;
    }
    return l;
}

bool canPlace(
    vector<int>& stalls,
    int k,
    int dist) {
    int count = 1;
    int last = stalls[0];
    for (int i = 1; i < stalls.size(); i++) {
        if (stalls[i] - last >= dist) {
            count++;
            last = stalls[i];
            if (count >= k)
                return true;
        }
    }
    return false;
}
int aggressiveCows(
    vector<int>& stalls,
    int k) {
    sort(stalls.begin(), stalls.end());
    int l = 0;
    int r = stalls.back() - stalls.front();
    while (l < r) {
        int mid =
            l + (r - l + 1) / 2;
        if (canPlace(stalls, k, mid))
            l = mid;
        else
            r = mid - 1;
    }
    return l;
}

int kthSmallest(
    vector<vector<int>>& matrix,
    int k) {
    int n = matrix.size();
    int l = matrix[0][0];
    int r = matrix[n - 1][n - 1];
    while (l < r) {
        int mid =
            l + (r - l) / 2;
        int count = 0;
        for (int i = 0; i < n; i++) {
            count += upper_bound(
                matrix[i].begin(),
                matrix[i].end(),
                mid
            ) - matrix[i].begin();
        }
        if (count < k)
            l = mid + 1;
        else
            r = mid;
    }
    return l;
}

long long integerSqrt(long long x) {
    long long l = 0;
    long long r = x;
    long long ans = 0;
    while (l <= r) {
        long long mid =
            l + (r - l) / 2;
        if (mid <= x / mid) {
            ans = mid;
            l = mid + 1;
        }
        else {
            r = mid - 1;
        }
    }
    return ans;
}

double squareRoot(double x) {
    double l = 0;
    double r = max(1.0, x);
    for (int i = 0; i < 100; i++) {
        double mid = (l + r) / 2;
        if (mid * mid < x)
            l = mid;
        else
            r = mid;
    }
    return l;
}

int exponentialSearch(
    vector<int>& arr,
    int target) {
    int n = arr.size();
    if (n == 0)
        return -1;
    if (arr[0] == target)
        return 0;
    int i = 1;
    while (i < n &&
           arr[i] < target) {
        i *= 2;
    }
    int l = i / 2;
    int r = min(i, n - 1);
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == target)
            return mid;
        if (arr[mid] < target)
            l = mid + 1;
        else
            r = mid - 1;
    }
    return -1;
}

double ternarySearch(
