    for (int i = 0; i < 100; i++) {
        double m1 =
            l + (r - l) / 3.0;
        double m2 =
            r - (r - l) / 3.0;
        if (f(m1) < f(m2))
            l = m1;
        else
            r = m2;
    }
    return (l + r) / 2;
}

void mergeArray(
    vector<int>& arr,
    int l,
    int mid,
    int r) {
    vector<int> temp;
    int i = l;
    int j = mid + 1;
    while (i <= mid && j <= r) {
        if (arr[i] <= arr[j])
            temp.push_back(arr[i++]);
        else
            temp.push_back(arr[j++]);
    }
    while (i <= mid)
        temp.push_back(arr[i++]);
    while (j <= r)
        temp.push_back(arr[j++]);
    for (int k = 0; k < temp.size(); k++)
        arr[l + k] = temp[k];
}
void mergeSort(
    vector<int>& arr,
    int l,
    int r) {
    if (l >= r)
        return;
    int mid =
        l + (r - l) / 2;
    mergeSort(arr, l, mid);
    mergeSort(arr, mid + 1, r);
    mergeArray(arr, l, mid, r);
}

int partitionArray(
    vector<int>& arr,
    int l,
    int r) {
    int pivot = arr[r];
    int i = l;
    for (int j = l; j < r; j++) {
        if (arr[j] <= pivot) {
            swap(arr[i], arr[j]);
            i++;
        }
    }
    swap(arr[i], arr[r]);
    return i;
}
void quickSort(
    vector<int>& arr,
    int l,
    int r) {
    if (l >= r)
        return;
    int p = partitionArray(arr, l, r);
    quickSort(arr, l, p - 1);
    quickSort(arr, p + 1, r);
}

int randomizedPartition(
    vector<int>& arr,
    int l,
    int r) {
    int pivotIndex =
        l + rand() % (r - l + 1);
    swap(arr[pivotIndex], arr[r]);
    return partitionArray(arr, l, r);
}
void randomizedQuickSort(
    vector<int>& arr,
    int l,
    int r) {
    if (l >= r)
        return;
    int p =
        randomizedPartition(arr, l, r);
    randomizedQuickSort(arr, l, p - 1);
    randomizedQuickSort(arr, p + 1, r);
}
