void heapify(
    vector<int>& arr,
    int n,
    int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < n &&
        arr[left] > arr[largest])
        largest = left;
    if (right < n &&
        arr[right] > arr[largest])
        largest = right;
    if (largest != i) {
        swap(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}
void heapSort(vector<int>& arr) {
    int n = arr.size();
    // Build heap
    for (int i = n / 2 - 1; i >= 0; i--)
        heapify(arr, n, i);
    // Extract maximum
    for (int i = n - 1; i > 0; i--) {
        swap(arr[0], arr[i]);
        heapify(arr, i, 0);
    }
}

int quickSelect(
    vector<int>& arr,
    int l,
    int r,
    int k) {
    while (l <= r) {
        int p =
            partitionArray(arr, l, r);
        if (p == k)
            return arr[p];
        if (p > k)
            r = p - 1;
        else
            l = p + 1;
    }
    return -1;
}

