void countingSort(vector<int>& arr) {
    if (arr.empty())
        return;
    int mn = *min_element(
        arr.begin(), arr.end());
    int mx = *max_element(
        arr.begin(), arr.end());
    vector<int> cnt(mx - mn + 1, 0);
    for (int x : arr)
        cnt[x - mn]++;
    int idx = 0;
    for (int i = 0; i < cnt.size(); i++) {
        while (cnt[i]--) {
            arr[idx++] = i + mn;
        }
    }
}

void countingSortDigit(
    vector<int>& arr,
    int exp) {
    int n = arr.size();
    vector<int> output(n);
    int cnt[10] = {};
    for (int x : arr)
        cnt[(x / exp) % 10]++;
    for (int i = 1; i < 10; i++)
        cnt[i] += cnt[i - 1];
    for (int i = n - 1; i >= 0; i--) {
        int digit =
            (arr[i] / exp) % 10;
        output[cnt[digit] - 1] =
            arr[i];
        cnt[digit]--;
    }
    arr = output;
}
void radixSort(vector<int>& arr) {
    if (arr.empty())
        return;
    int mx =
        *max_element(
            arr.begin(),
            arr.end());
    for (int exp = 1;
         mx / exp > 0;
         exp *= 10) {
        countingSortDigit(arr, exp);
    }
}

void bucketSort(vector<double>& arr) {
    int n = arr.size();
    vector<vector<double>> buckets(n);
    for (double x : arr) {
        int idx =
            min(n - 1,
                (int)(x * n));
        buckets[idx].push_back(x);
    }
    for (auto& bucket : buckets)
        sort(bucket.begin(), bucket.end());
    int idx = 0;
    for (auto& bucket : buckets) {
        for (double x : bucket)
            arr[idx++] = x;
    }
}

void sort012(vector<int>& arr) {
    int low = 0;
    int mid = 0;
    int high = arr.size() - 1;
    while (mid <= high) {
        if (arr[mid] == 0) {
            swap(arr[low], arr[mid]);
            low++;
            mid++;
        }
        else if (arr[mid] == 1) {
            mid++;
        }
        else {
            swap(arr[mid], arr[high]);
            high--;
        }
    }
}

