vector<vector<int>> mergeIntervals(
    vector<vector<int>>& intervals) {
    if (intervals.empty())
        return {};
    sort(intervals.begin(),
         intervals.end());
    vector<vector<int>> ans;
    ans.push_back(intervals[0]);
    for (int i = 1;
         i < intervals.size();
         i++) {
        if (intervals[i][0] <=
            ans.back()[1]) {
            ans.back()[1] =
                max(ans.back()[1],
                    intervals[i][1]);
        }
        else {
            ans.push_back(intervals[i]);
        }
    }
    return ans;
}

long long mergeAndCount(
    vector<int>& arr,
    int l,
    int mid,
    int r) {
    vector<int> temp;
    int i = l;
    int j = mid + 1;
    long long inv = 0;
    while (i <= mid &&
           j <= r) {
        if (arr[i] <= arr[j]) {
            temp.push_back(arr[i++]);
        }
        else {
            temp.push_back(arr[j++]);
            inv += mid - i + 1;
        }
    }
    while (i <= mid)
        temp.push_back(arr[i++]);
    while (j <= r)
        temp.push_back(arr[j++]);
    for (int k = 0;
         k < temp.size();
         k++) {
        arr[l + k] = temp[k];
    }
    return inv;
}
long long countInversions(
    vector<int>& arr,
    int l,
    int r) {
    if (l >= r)
        return 0;
    int mid =
        l + (r - l) / 2;
    long long ans = 0;
    ans += countInversions(
        arr, l, mid);
    ans += countInversions(
        arr, mid + 1, r);
    ans += mergeAndCount(
        arr, l, mid, r);
    return ans;
}

vector<int> coordinateCompress(
    vector<int> arr) {
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(
        unique(vals.begin(), vals.end()),
        vals.end()
    );
    vector<int> ans;
    for (int x : arr) {
        int rank =
            lower_bound(
                vals.begin(),
                vals.end(),
                x
            ) - vals.begin();
        ans.push_back(rank);
    }
    return ans;
}

void quickSort3(
    vector<int>& arr,
    int l,
    int r) {
    if (l >= r)
        return;
    int pivot = arr[l];
    int lt = l;
    int i = l;
    int gt = r;
    while (i <= gt) {
        if (arr[i] < pivot) {
            swap(arr[lt], arr[i]);
            lt++;
            i++;
        }
        else if (arr[i] > pivot) {
            swap(arr[i], arr[gt]);
            gt--;
        }
        else {
            i++;
        }
    }
    quickSort3(arr, l, lt - 1);
    quickSort3(arr, gt + 1, r);
}

