pair<int, int> twoUniques(vector<int>& arr) {
    int xorAll = 0;
    for (int x : arr)
        xorAll ^= x;
    // Rightmost bit where the two numbers differ
    int bit = xorAll & -xorAll;
    int a = 0;
    int b = 0;
    for (int x : arr) {
        if (x & bit)
            a ^= x;
        else
            b ^= x;
    }
    return {a, b};
}

