int n;
int cost[20][20];
int dp[1 << 20];
int solve(int mask) {
    int worker = __builtin_popcount(mask);
    if (worker == n)
        return 0;
    if (dp[mask] != -1)
        return dp[mask];
    int ans = INT_MAX;
    for (int job = 0; job < n; job++) {
        if (!(mask & (1 << job))) {
            ans = min(
                ans,
                cost[worker][job] +
                solve(mask | (1 << job))
            );
        }
    }
    return dp[mask] = ans;
}

int n;
int cost[20][20];
int dp[1 << 20][20];
int tsp(int mask, int u) {
    if (mask == (1 << n) - 1)
        return cost[u][0];
    int& ans = dp[mask][u];
    if (ans != -1)
        return ans;
    ans = INT_MAX;
    for (int v = 0; v < n; v++) {
        if (!(mask & (1 << v))) {
            ans = min(
                ans,
                cost[u][v] +
                tsp(mask | (1 << v), v)
            );
        }
    }
    return ans;
}

