int findMaximumXOR(vector<int>& arr) {
    int ans = 0;
    int mask = 0;
    for (int bit = 31; bit >= 0; bit--) {
        mask |= (1 << bit);
        unordered_set<int> prefixes;
        for (int x : arr)
            prefixes.insert(x & mask);
        int candidate = ans | (1 << bit);
        for (int x : arr) {
            int prefix = x & mask;
            if (prefixes.count(prefix ^ candidate)) {
                ans = candidate;
                break;
            }
        }
    }
    return ans;
}

