class BinaryTrie {
public:
    TrieNode* root;
    BinaryTrie() {
        root = new TrieNode();
    }
    void insert(int x) {
        TrieNode* node = root;
        for (int bit = 31; bit >= 0; bit--) {
            int b = (x >> bit) & 1;
            if (!node->child[b])
                node->child[b] = new TrieNode();
            node = node->child[b];
        }
    }
    int getMaxXOR(int x) {
        TrieNode* node = root;
        int ans = 0;
        for (int bit = 31; bit >= 0; bit--) {
            int b = (x >> bit) & 1;
            int opposite = b ^ 1;
            if (node->child[opposite]) {
                ans |= (1 << bit);
                node = node->child[opposite];
            }
            else {
                node = node->child[b];
            }
        }
        return ans;
    }
};

