bool isPrime(long long n, int k = 5) {
    if (n < 2)
        return false;
    if (n == 2 || n == 3)
        return true;
    if (n % 2 == 0)
        return false;
    long long d = n - 1;
    int r = 0;
    while (d % 2 == 0) {
        d /= 2;
        r++;
    }
    for (int iteration = 0; iteration < k; iteration++) {
        long long a = 2 + rand() % (n - 3);
        long long x = modExp(a, d, n);
        if (x == 1 || x == n - 1)
            continue;
        bool composite = true;
        for (int i = 1; i < r; i++) {
            x = (__int128)x * x % n;
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;
}

long long CRT(vector<long long>& nums,
              vector<long long>& rems) {
    int n = nums.size();
    long long prod = 1;
    for (long long x : nums)
        prod *= x;
    long long result = 0;
    for (int i = 0; i < n; i++) {
        long long pp = prod / nums[i];
        long long inv = modInverse(pp, nums[i]);
        result += rems[i] * inv * pp;
        result %= prod;
    }
    return (result % prod + prod) % prod;
}

long long binaryGCD(long long a, long long b) {
    if (a == 0)
        return b;
    if (b == 0)
        return a;
    int shift = 0;
    // Both even
    while (((a | b) & 1) == 0) {
        a >>= 1;
        b >>= 1;
        shift++;
    }
    // Make a odd
    while ((a & 1) == 0)
        a >>= 1;
    while (b != 0) {
        // Make b odd
        while ((b & 1) == 0)
            b >>= 1;
        if (a > b)
            swap(a, b);
        b -= a;
    }
    return a << shift;
}

vector<long long> fact;
vector<long long> invFact;
void precompute(int N, long long p) {
    fact.resize(N + 1);
    invFact.resize(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) {
        fact[i] = fact[i - 1] * i % p;
    }
    invFact[N] = modExp(fact[N], p - 2, p);
    for (int i = N - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % p;
    }
}

long long nCr(int n, int r, long long p) {
    if (r < 0 || r > n)
        return 0;
    return fact[n] * invFact[r] % p
                 * invFact[n - r] % p;
}

string longestPalindrome(string s) {
    int n = s.size();
    int bestL = 0, bestR = 0;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < n && s[l] == s[r]) {
            if (r - l > bestR - bestL) {
                bestL = l;
                bestR = r;
            }
            l--;
            r++;
        }
    };
    for (int i = 0; i < n; i++) {
        expand(i, i);       // Odd length
        expand(i, i + 1);   // Even length
    }
    return s.substr(bestL, bestR - bestL + 1);
}

int LCS(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1,
                           vector<int>(m + 1, 0));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] =
                    1 + dp[i - 1][j - 1];
            }
            else {
                dp[i][j] =
                    max(dp[i - 1][j],
                        dp[i][j - 1]);
            }
        }
    }
    return dp[n][m];
}

int longestCommonSubstring(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1,
                           vector<int>(m + 1, 0));
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] =
                    dp[i - 1][j - 1] + 1;
                ans = max(ans, dp[i][j]);
            }
        }
    }
    return ans;
}

int editDistance(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1,
                           vector<int>(m + 1));
    for (int i = 0; i <= n; i++)
        dp[i][0] = i;
    for (int j = 0; j <= m; j++)
        dp[0][j] = j;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] =
                    dp[i - 1][j - 1];
            }
            else {
                dp[i][j] = 1 + min({
                    dp[i - 1][j],     // Delete
                    dp[i][j - 1],     // Insert
                    dp[i - 1][j - 1]  // Replace
                });
            }
        }
    }
    return dp[n][m];
}

vector<int> computeLPS(string pat) {
    int n = pat.size();
    vector<int> lps(n, 0);
    int len = 0;
    for (int i = 1; i < n; i++) {
        while (len > 0 &&
               pat[i] != pat[len]) {
            len = lps[len - 1];
        }
        if (pat[i] == pat[len])
            len++;
        lps[i] = len;
    }
    return lps;
}

vector<int> KMP(string text, string pat) {
    vector<int> ans;
    if (pat.empty())
        return ans;
    vector<int> lps = computeLPS(pat);
    int n = text.size();
    int m = pat.size();
    int i = 0;
    int j = 0;
    while (i < n) {
        if (text[i] == pat[j]) {
            i++;
            j++;
        }
        if (j == m) {
            ans.push_back(i - j);
            j = lps[j - 1];
        }
        else if (i < n &&
                 text[i] != pat[j]) {
            if (j > 0)
                j = lps[j - 1];
            else
                i++;
        }
    }
    return ans;
}

vector<int> ZAlgorithm(string s) {
    int n = s.size();
    vector<int> z(n, 0);
    int l = 0;
    int r = 0;
    for (int i = 1; i < n; i++) {
        if (i <= r)
            z[i] = min(r - i + 1,
                       z[i - l]);
        while (i + z[i] < n &&
               s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    return z;
}

vector<int> rabinKarp(string text, string pat) {
    vector<int> ans;
    int n = text.size();
    int m = pat.size();
    if (m > n)
        return ans;
    const long long MOD = 1000000007;
    const long long BASE = 31;
    long long patHash = 0;
    long long textHash = 0;
    long long power = 1;
    for (int i = 0; i < m; i++) {
        patHash =
            (patHash * BASE + pat[i]) % MOD;
        textHash =
            (textHash * BASE + text[i]) % MOD;
        if (i < m - 1)
            power = power * BASE % MOD;
    }
    for (int i = 0; i <= n - m; i++) {
        if (patHash == textHash) {
            if (text.compare(i, m, pat) == 0)
                ans.push_back(i);
        }
        if (i < n - m) {
            textHash =
                (textHash -
                 text[i] * power % MOD +
                 MOD) % MOD;
            textHash =
                (textHash * BASE +
                 text[i + m]) % MOD;
        }
    }
    return ans;
}

string manacher(string s) {
    string t = "^";
    for (char c : s) {
        t += '#';
        t += c;
    }
    t += "#$";
    int n = t.size();
    vector<int> p(n, 0);
    int center = 0;
    int right = 0;
    int bestCenter = 0;
    int bestLen = 0;
    for (int i = 1; i < n - 1; i++) {
        int mirror = 2 * center - i;
        if (i < right)
            p[i] = min(right - i,
                       p[mirror]);
        while (t[i + 1 + p[i]] ==
               t[i - 1 - p[i]]) {
            p[i]++;
        }
        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
        }
        if (p[i] > bestLen) {
            bestLen = p[i];
            bestCenter = i;
        }
    }
    int start = (bestCenter - bestLen) / 2;
    return s.substr(start, bestLen);
}

class Trie {
    struct Node {
        Node* child[26];
        bool end;
        Node() {
            end = false;
            for (int i = 0; i < 26; i++)
                child[i] = nullptr;
        }
    };
    Node* root;
public:
    Trie() {
        root = new Node();
    }
    void insert(string word) {
        Node* cur = root;
        for (char c : word) {
            int x = c - 'a';
            if (!cur->child[x])
                cur->child[x] = new Node();
            cur = cur->child[x];
        }
        cur->end = true;
    }
    bool search(string word) {
        Node* cur = root;
        for (char c : word) {
            int x = c - 'a';
            if (!cur->child[x])
                return false;
            cur = cur->child[x];
        }
        return cur->end;
    }
    bool startsWith(string prefix) {
        Node* cur = root;
        for (char c : prefix) {
            int x = c - 'a';
            if (!cur->child[x])
                return false;
            cur = cur->child[x];
        }
        return true;
    }
};

class AhoCorasick {
    struct Node {
        int child[26];
        int link;
        vector<int> output;
        Node() {
            fill(child, child + 26, -1);
            link = 0;
        }
    };
    vector<Node> trie;
public:
    AhoCorasick() {
        trie.emplace_back();
    }
    void insert(string s, int id) {
        int cur = 0;
        for (char c : s) {
            int x = c - 'a';
            if (trie[cur].child[x] == -1) {
                trie[cur].child[x] =
                    trie.size();
                trie.emplace_back();
            }
            cur = trie[cur].child[x];
        }
        trie[cur].output.push_back(id);
    }
    void build() {
        queue<int> q;
        for (int c = 0; c < 26; c++) {
            int nxt = trie[0].child[c];
            if (nxt != -1) {
                trie[nxt].link = 0;
                q.push(nxt);
            }
            else {
                trie[0].child[c] = 0;
            }
        }
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            int link = trie[v].link;
            for (int id : trie[link].output)
                trie[v].output.push_back(id);
            for (int c = 0; c < 26; c++) {
                int nxt = trie[v].child[c];
                if (nxt != -1) {
                    trie[nxt].link =
                        trie[link].child[c];
                    q.push(nxt);
                }
                else {
                    trie[v].child[c] =
                        trie[link].child[c];
                }
            }
        }
    }
};

class StringHash {
    static const long long MOD = 1000000007;
    static const long long BASE = 911382323;
    vector<long long> h;
    vector<long long> power;
public:
    StringHash(string s) {
        int n = s.size();
        h.resize(n + 1);
        power.resize(n + 1);
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            h[i + 1] =
                (h[i] * BASE + s[i]) % MOD;
            power[i + 1] =
                power[i] * BASE % MOD;
        }
    }
    long long getHash(int l, int r) {
        // [l, r)
        return (h[r] -
                h[l] * power[r - l] % MOD +
                MOD) % MOD;
    }
};

