int longestPalindromicSubsequence(string s) {
    int n = s.size();
    vector<vector<int>> dp(
        n, vector<int>(n, 0)
    );
    for (int i = 0; i < n; i++)
        dp[i][i] = 1;
    for (int len = 2; len <= n; len++) {
        for (int l = 0;
             l + len - 1 < n;
             l++) {
            int r = l + len - 1;
            if (s[l] == s[r]) {
                dp[l][r] =
                    2 + (len == 2
                         ? 0
                         : dp[l + 1][r - 1]);
            }
            else {
                dp[l][r] =
                    max(dp[l + 1][r],
                        dp[l][r - 1]);
            }
        }
    }
    return dp[0][n - 1];
}

string minWindow(string s, string t) {
    unordered_map<char, int> need;
    unordered_map<char, int> have;
    for (char c : t)
        need[c]++;
    int required = need.size();
    int formed = 0;
    int l = 0;
    int bestLen = INT_MAX;
    int bestL = 0;
    for (int r = 0; r < s.size(); r++) {
        char c = s[r];
        have[c]++;
        if (need.count(c) &&
            have[c] == need[c]) {
            formed++;
        }
        while (formed == required) {
            if (r - l + 1 < bestLen) {
                bestLen = r - l + 1;
                bestL = l;
            }
            char x = s[l];
            have[x]--;
            if (need.count(x) &&
                have[x] < need[x]) {
                formed--;
            }
            l++;
        }
    }
    if (bestLen == INT_MAX)
        return "";
    return s.substr(bestL, bestLen);
}

string smallestSubsequence(string s) {
    vector<int> last(256, -1);
    for (int i = 0; i < s.size(); i++)
        last[(unsigned char)s[i]] = i;
    vector<bool> seen(256, false);
    string st;
    for (int i = 0; i < s.size(); i++) {
        unsigned char c = s[i];
        if (seen[c])
            continue;
        while (!st.empty() &&
               st.back() > c &&
               last[(unsigned char)st.back()] > i) {
            seen[(unsigned char)st.back()] = false;
            st.pop_back();
        }
        st.push_back(c);
        seen[c] = true;
    }
    return st;
}

vector<int> suffixArray(string s) {
    int n = s.size();
    vector<int> sa(n);
    vector<int> rank(n);
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        rank[i] = s[i];
    }
    for (int k = 1; k < n; k *= 2) {
        auto cmp = [&](int i, int j) {
            if (rank[i] != rank[j])
                return rank[i] < rank[j];
            int ri =
                i + k < n ? rank[i + k] : -1;
            int rj =
                j + k < n ? rank[j + k] : -1;
            return ri < rj;
        };
        sort(sa.begin(), sa.end(), cmp);
        vector<int> newRank(n);
        newRank[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            newRank[sa[i]] =
                newRank[sa[i - 1]] +
                cmp(sa[i - 1], sa[i]);
        }
        rank = newRank;
        if (rank[sa[n - 1]] == n - 1)
            break;
    }
    return sa;
}

vector<int> buildLCP(
    string s,
    vector<int>& sa) {
    int n = s.size();
    vector<int> rank(n);
    for (int i = 0; i < n; i++)
        rank[sa[i]] = i;
    vector<int> lcp(n, 0);
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] == n - 1) {
            k = 0;
            continue;
        }
        int j = sa[rank[i] + 1];
        while (i + k < n &&
               j + k < n &&
               s[i + k] == s[j + k]) {
            k++;
        }
        lcp[rank[i]] = k;
        if (k > 0)
            k--;
    }
    return lcp;
}

