    unordered_set<string> dict(
        words.begin(),
        words.end()
    );
    int n = s.size();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] &&
                dict.count(
                    s.substr(j, i - j)
                )) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[n];
}

struct State {
    int len;
    int link;
    int next[26];
    State() {
        len = 0;
        link = -1;
        fill(next, next + 26, -1);
    }
};
vector<State> st(2 * N);
int sz = 1;
int last = 0;
void extend(char ch) {
    int c = ch - 'a';
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    int p = last;
    while (p != -1 &&
           st[p].next[c] == -1) {
        st[p].next[c] = cur;
        p = st[p].link;
    }
    if (p == -1) {
        st[cur].link = 0;
    }
    else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        }
        else {
            int clone = sz++;
            st[clone] = st[q];
            st[clone].len =
                st[p].len + 1;
            while (p != -1 &&
                   st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = clone;
            st[cur].link = clone;
        }
    }
    last = cur;
}

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};
ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* curr = head;
    while (curr) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

ListNode* reverseRecursive(ListNode* head) {
    if (!head || !head->next)
        return head;
    ListNode* newHead =
        reverseRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return newHead;
}

ListNode* reverseKGroup(
    ListNode* head,
    int k) {
    ListNode* curr = head;
    int count = 0;
    while (curr && count < k) {
        curr = curr->next;
        count++;
    }
    if (count < k)
        return head;
    curr = head;
    ListNode* prev = nullptr;
    for (int i = 0; i < k; i++) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    head->next =
        reverseKGroup(curr, k);
    return prev;
}

ListNode* reverseBetween(
    ListNode* head,
    int left,
    int right) {
    if (!head || left == right)
        return head;
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    for (int i = 1; i < left; i++)
        prev = prev->next;
    ListNode* curr = prev->next;
    for (int i = 0;
         i < right - left;
         i++) {
        ListNode* next = curr->next;
        curr->next = next->next;
        next->next = prev->next;
        prev->next = next;
    }
    return dummy.next;
}

bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast)
            return true;
    }
    return false;
}

ListNode* detectCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) {
                slow = slow->next;
                fast = fast->next;
            }
            return slow;
        }
    }
    return nullptr;
}

ListNode* middleNode(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

bool isPalindrome(ListNode* head) {
    if (!head || !head->next)
        return true;
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* second =
        reverseList(slow);
    ListNode* first = head;
    while (second) {
        if (first->val != second->val)
            return false;
        first = first->next;
        second = second->next;
    }
    return true;
}

ListNode* mergeTwoLists(
    ListNode* l1,
    ListNode* l2) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;
            l1 = l1->next;
        }
        else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
    tail->next =
        l1 ? l1 : l2;
    return dummy.next;
}

struct Compare {
    bool operator()(
        ListNode* a,
        ListNode* b) {
        return a->val > b->val;
    }
};
ListNode* mergeKLists(
    vector<ListNode*>& lists) {
    priority_queue<
        ListNode*,
        vector<ListNode*>,
        Compare
    > pq;
    for (ListNode* head : lists) {
        if (head)
            pq.push(head);
    }
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (!pq.empty()) {
        ListNode* node = pq.top();
        pq.pop();
        tail->next = node;
        tail = node;
        if (node->next)
            pq.push(node->next);
    }
    return dummy.next;
}

ListNode* mergeRange(
    vector<ListNode*>& lists,
    int l,
    int r) {
    if (l == r)
        return lists[l];
    int mid = l + (r - l) / 2;
    ListNode* left =
        mergeRange(lists, l, mid);
    ListNode* right =
        mergeRange(lists, mid + 1, r);
    return mergeTwoLists(left, right);
}
ListNode* mergeKListsDC(
    vector<ListNode*>& lists) {
    if (lists.empty())
        return nullptr;
    return mergeRange(
        lists,
        0,
        lists.size() - 1
    );
}

ListNode* removeNthFromEnd(
    ListNode* head,
    int n) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* first = &dummy;
    ListNode* second = &dummy;
    for (int i = 0; i <= n; i++)
        first = first->next;
    while (first) {
        first = first->next;
        second = second->next;
    }
    second->next =
        second->next->next;
    return dummy.next;
}

void deleteNode(ListNode* node) {
    node->val = node->next->val;
    node->next = node->next->next;
}

ListNode* sortList(ListNode* head) {
    if (!head || !head->next)
        return head;
    ListNode* slow = head;
    ListNode* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* mid = slow->next;
    slow->next = nullptr;
    ListNode* left =
        sortList(head);
    ListNode* right =
        sortList(mid);
    return mergeTwoLists(left, right);
}

ListNode* addTwoNumbers(
    ListNode* l1,
    ListNode* l2) {
    ListNode dummy(0);
    ListNode* curr = &dummy;
    int carry = 0;
    while (l1 || l2 || carry) {
        int sum = carry;
        if (l1) {
            sum += l1->val;
            l1 = l1->next;
        }
        if (l2) {
            sum += l2->val;
            l2 = l2->next;
        }
        curr->next =
            new ListNode(sum % 10);
        carry = sum / 10;
        curr = curr->next;
    }
    return dummy.next;
}

struct Node {
    int val;
    Node* prev;
    Node* next;
    Node* child;
};
Node* flatten(Node* head) {
    if (!head)
        return head;
    Node* curr = head;
    while (curr) {
        if (curr->child) {
            Node* child =
                curr->child;
            Node* next =
                curr->next;
            curr->next = child;
            child->prev = curr;
            curr->child = nullptr;
            Node* tail = child;
            while (tail->next)
                tail = tail->next;
            tail->next = next;
            if (next)
                next->prev = tail;
        }
        curr = curr->next;
    }
    return head;
}

Node* flattenDFS(Node* head) {
    if (!head)
        return nullptr;
    Node* curr = head;
    while (curr) {
        if (curr->child) {
            Node* next =
                curr->next;
            Node* child =
                curr->child;
            curr->next = child;
            child->prev = curr;
            curr->child = nullptr;
            Node* tail =
                flattenDFS(child);
            tail->next = next;
            if (next)
                next->prev = tail;
        }
        curr = curr->next;
    }
    return head;
}

struct RandomNode {
    int val;
    RandomNode* next;
    RandomNode* random;
    RandomNode(int x)
        : val(x),
          next(nullptr),
          random(nullptr) {}
};
RandomNode* copyRandomList(
    RandomNode* head) {
    if (!head)
        return nullptr;
    unordered_map<
        RandomNode*,
        RandomNode*
    > mp;
    RandomNode* curr = head;
    while (curr) {
        mp[curr] =
            new RandomNode(curr->val);
        curr = curr->next;
    }
    curr = head;
    while (curr) {
        mp[curr]->next =
            curr->next
                ? mp[curr->next]
                : nullptr;
        mp[curr]->random =
            curr->random
                ? mp[curr->random]
                : nullptr;
        curr = curr->next;
    }
    return mp[head];
}

RandomNode* copyRandomListO1(
    RandomNode* head) {
    if (!head)
        return nullptr;
    // 1. Insert copied node after every node
    RandomNode* curr = head;
    while (curr) {
        RandomNode* copy =
            new RandomNode(curr->val);
        copy->next = curr->next;
        curr->next = copy;
        curr = copy->next;
    }
    // 2. Set random pointers
    curr = head;
    while (curr) {
        if (curr->random)
            curr->next->random =
                curr->random->next;
        curr = curr->next->next;
    }
    // 3. Separate the lists
    curr = head;
    RandomNode* newHead =
        head->next;
    while (curr) {
        RandomNode* copy =
            curr->next;
        curr->next =
            copy->next;
        if (copy->next)
            copy->next =
                copy->next->next;
        curr = curr->next;
    }
    return newHead;
}

ListNode* getIntersectionNode(
    ListNode* headA,
    ListNode* headB) {
    ListNode* a = headA;
    ListNode* b = headB;
    while (a != b) {
        a = a ? a->next : headB;
        b = b ? b->next : headA;
    }
    return a;
}

void reorderList(ListNode* head) {
    if (!head || !head->next)
        return;
    // Find middle
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast &&
           fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    // Reverse second half
    ListNode* second =
        reverseList(slow->next);
    slow->next = nullptr;
    // Merge alternately
    ListNode* first = head;
    while (second) {
        ListNode* next1 =
            first->next;
        ListNode* next2 =
            second->next;
        first->next = second;
        second->next = next1;
        first = next1;
        second = next2;
    }
}

ListNode* partition(
    ListNode* head,
    int x) {
    ListNode smallDummy(0);
    ListNode largeDummy(0);
    ListNode* small =
        &smallDummy;
    ListNode* large =
        &largeDummy;
    while (head) {
        if (head->val < x) {
            small->next = head;
            small = small->next;
        }
        else {
            large->next = head;
            large = large->next;
        }
        head = head->next;
    }
    large->next = nullptr;
    small->next = largeDummy.next;
    return smallDummy.next;
}

ListNode* oddEvenList(
    ListNode* head) {
    if (!head || !head->next)
        return head;
    ListNode* odd = head;
    ListNode* even = head->next;
    ListNode* evenHead = even;
    while (even &&
           even->next) {
        odd->next = even->next;
        odd = odd->next;
        even->next = odd->next;
        even = even->next;
    }
    odd->next = evenHead;
    return head;
}

int cycleLength(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast &&
           fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            int len = 1;
            fast = fast->next;
            while (fast != slow) {
                fast = fast->next;
                len++;
            }
            return len;
        }
    }
    return 0;
}

void removeCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast &&
           fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast)
            break;
    }
    if (!fast || !fast->next)
        return;
    slow = head;
    while (slow != fast) {
        slow = slow->next;
        fast = fast->next;
    }
    ListNode* cycleStart = slow;
    ListNode* curr = cycleStart;
    while (curr->next != cycleStart)
        curr = curr->next;
    curr->next = nullptr;
}

class LRUCache {
    struct Node {
        int key;
        int value;
        Node* prev;
        Node* next;
        Node(int k, int v)
            : key(k),
              value(v),
              prev(nullptr),
              next(nullptr) {}
    };
    int capacity;
    unordered_map<int, Node*> mp;
    Node* head;
    Node* tail;
    void remove(Node* node) {
        node->prev->next =
            node->next;
        node->next->prev =
            node->prev;
    }
    void insertFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }
public:
    LRUCache(int capacity) {
        this->capacity = capacity;
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head->next = tail;
        tail->prev = head;
    }
    int get(int key) {
        if (!mp.count(key))
            return -1;
        Node* node = mp[key];
        remove(node);
        insertFront(node);
        return node->value;
    }
    void put(int key, int value) {
        if (mp.count(key)) {
            Node* node = mp[key];
            node->value = value;
            remove(node);
            insertFront(node);
            return;
        }
        Node* node =
            new Node(key, value);
        mp[key] = node;
        insertFront(node);
        if (mp.size() > capacity) {
            Node* lru =
                tail->prev;
            mp.erase(lru->key);
            remove(lru);
            delete lru;
        }
    }
};

vector<ListNode*> splitListToParts(
    ListNode* head,
    int k) {
    int n = 0;
    ListNode* curr = head;
    while (curr) {
        n++;
        curr = curr->next;
    }
    int base = n / k;
    int extra = n % k;
    vector<ListNode*> ans(k);
    curr = head;
    for (int i = 0; i < k; i++) {
        ans[i] = curr;
        int size =
            base + (i < extra);
        for (int j = 1;
             j < size;
             j++) {
            if (curr)
                curr = curr->next;
        }
        if (curr) {
            ListNode* next =
                curr->next;
            curr->next = nullptr;
            curr = next;
        }
    }
    return ans;
}

ListNode* rotateRight(
    ListNode* head,
    int k) {
    if (!head || !head->next || k == 0)
        return head;
    int n = 1;
    ListNode* tail = head;
    while (tail->next) {
        tail = tail->next;
        n++;
    }
    k %= n;
    if (k == 0)
        return head;
    tail->next = head;
    int steps = n - k;
    while (steps--)
        tail = tail->next;
    head = tail->next;
    tail->next = nullptr;
    return head;
}

ListNode* reverseAlternateK(
    ListNode* head,
    int k) {
    ListNode* curr = head;
    ListNode* prev = nullptr;
    int count = 0;
    while (curr && count < k) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
        count++;
    }
    if (head)
        head->next = curr;
    count = 0;
    while (curr && count < k) {
        curr = curr->next;
        count++;
    }
    if (curr)
        head->next =
            reverseAlternateK(curr, k);
    return prev;
}

vector<int> nextGreater(vector<int>& arr) {
    int n = arr.size();
    vector<int> ans(n, -1);
    stack<int> st;
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() &&
               st.top() <= arr[i]) {
            st.pop();
        }
        if (!st.empty())
            ans[i] = st.top();
        st.push(arr[i]);
    }
    return ans;
}

vector<int> nextGreaterElements(
    vector<int>& nums) {
    int n = nums.size();
    vector<int> ans(n, -1);
    stack<int> st;
    for (int i = 2 * n - 1;
         i >= 0;
         i--) {
        int idx = i % n;
        while (!st.empty() &&
               st.top() <= nums[idx]) {
            st.pop();
        }
        if (i < n && !st.empty())
            ans[idx] = st.top();
        st.push(nums[idx]);
    }
    return ans;
}

