int largestRectangleArea(
    vector<int>& heights) {
    int n = heights.size();
    stack<int> st;
    int ans = 0;
    for (int i = 0; i <= n; i++) {
        int curr =
            (i == n ? 0 : heights[i]);
        while (!st.empty() &&
               curr < heights[st.top()]) {
            int h = heights[st.top()];
            st.pop();
            int width;
            if (st.empty())
                width = i;
            else
                width = i - st.top() - 1;
            ans = max(
                ans,
                h * width
            );
        }
        st.push(i);
    }
    return ans;
}

int maximalRectangle(
    vector<vector<char>>& matrix) {
    if (matrix.empty())
        return 0;
    int m = matrix.size();
    int n = matrix[0].size();
    vector<int> heights(n, 0);
    int ans = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (matrix[i][j] == '1')
                heights[j]++;
            else
                heights[j] = 0;
        }
        ans = max(
            ans,
            largestRectangleArea(heights)
        );
    }
    return ans;
}

long long sumSubarrayMins(
    vector<int>& arr) {
    int n = arr.size();
    vector<int> left(n);
    vector<int> right(n);
    stack<int> st;
    // Previous smaller element
    for (int i = 0; i < n; i++) {
        while (!st.empty() &&
               arr[st.top()] > arr[i]) {
            st.pop();
        }
        if (st.empty())
            left[i] = i + 1;
        else
            left[i] = i - st.top();
        st.push(i);
    }
    while (!st.empty())
        st.pop();
    // Next smaller-or-equal element
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() &&
               arr[st.top()] >= arr[i]) {
            st.pop();
        }
        if (st.empty())
            right[i] = n - i;
        else
            right[i] = st.top() - i;
        st.push(i);
    }
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans +=
            1LL * arr[i] *
            left[i] *
            right[i];
    }
    return ans;
}

long long sumSubarrayRanges(
    vector<int>& nums) {
    int n = nums.size();
    long long ans = 0;
    // Contribution as maximum
    stack<int> st;
    for (int i = 0; i <= n; i++) {
        while (!st.empty() &&
              (i == n ||
               nums[st.top()] < nums[i])) {
            int j = st.top();
            st.pop();
            int left =
                st.empty()
                ? j + 1
                : j - st.top();
            int right = i - j;
            ans +=
                1LL * nums[j] *
                left * right;
        }
        st.push(i);
    }
    while (!st.empty())
        st.pop();
    // Contribution as minimum
    for (int i = 0; i <= n; i++) {
        while (!st.empty() &&
              (i == n ||
               nums[st.top()] > nums[i])) {
            int j = st.top();
            st.pop();
            int left =
                st.empty()
                ? j + 1
                : j - st.top();
            int right = i - j;
            ans -=
                1LL * nums[j] *
                left * right;
        }
        st.push(i);
    }
    return ans;
}

vector<int> maxSlidingWindow(
    vector<int>& nums,
    int k) {
    deque<int> dq;
    vector<int> ans;
    for (int i = 0;
         i < nums.size();
         i++) {
        // Remove expired indices
        while (!dq.empty() &&
               dq.front() <= i - k) {
            dq.pop_front();
        }
        // Maintain decreasing values
        while (!dq.empty() &&
               nums[dq.back()] <= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1)
            ans.push_back(
                nums[dq.front()]
            );
    }
    return ans;
}

vector<int> minSlidingWindow(
    vector<int>& nums,
    int k) {
    deque<int> dq;
    vector<int> ans;
    for (int i = 0;
         i < nums.size();
         i++) {
        while (!dq.empty() &&
               dq.front() <= i - k) {
            dq.pop_front();
        }
        while (!dq.empty() &&
               nums[dq.back()] >= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1)
            ans.push_back(
                nums[dq.front()]
            );
    }
    return ans;
}

vector<int> stockSpan(
    vector<int>& prices) {
    int n = prices.size();
    vector<int> ans(n);
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() &&
               prices[st.top()] <= prices[i]) {
            st.pop();
        }
        if (st.empty())
            ans[i] = i + 1;
        else
            ans[i] = i - st.top();
        st.push(i);
    }
    return ans;
}

class MinStack {
    stack<int> st;
    stack<int> minSt;
public:
    void push(int x) {
        st.push(x);
        if (minSt.empty() ||
            x <= minSt.top()) {
            minSt.push(x);
        }
    }
    void pop() {
        int x = st.top();
        st.pop();
        if (x == minSt.top())
            minSt.pop();
    }
    int top() {
        return st.top();
    }
    int getMin() {
        return minSt.top();
    }
};

class MaxStack {
    stack<int> st;
    stack<int> maxSt;
public:
    void push(int x) {
        st.push(x);
        if (maxSt.empty())
            maxSt.push(x);
        else
            maxSt.push(
                max(x, maxSt.top())
            );
    }
    void pop() {
        st.pop();
        maxSt.pop();
    }
    int top() {
        return st.top();
    }
    int getMax() {
        return maxSt.top();
    }
};

int evalPostfix(
    vector<string>& tokens) {
    stack<int> st;
    for (string& token : tokens) {
        if (isdigit(token[0]) ||
            (token.size() > 1 &&
             token[0] == '-')) {
            st.push(stoi(token));
        }
        else {
            int b = st.top();
            st.pop();
            int a = st.top();
            st.pop();
            if (token == "+")
                st.push(a + b);
            else if (token == "-")
                st.push(a - b);
            else if (token == "*")
                st.push(a * b);
            else
                st.push(a / b);
        }
    }
    return st.top();
}

int precedence(char op) {
    if (op == '^')
        return 3;
    if (op == '*' ||
        op == '/')
        return 2;
    if (op == '+' ||
        op == '-')
        return 1;
    return 0;
}
string infixToPostfix(
    string s) {
    stack<char> st;
    string ans;
    for (char c : s) {
        if (isalnum(c)) {
            ans += c;
        }
        else if (c == '(') {
            st.push(c);
        }
        else if (c == ')') {
            while (!st.empty() &&
                   st.top() != '(') {
                ans += st.top();
                st.pop();
            }
            st.pop();
        }
        else {
            while (!st.empty() &&
                   st.top() != '(' &&
                   precedence(st.top()) >=
                   precedence(c)) {
                ans += st.top();
                st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) {
        ans += st.top();
        st.pop();
    }
    return ans;
}

int calculate(string s) {
    stack<int> st;
    int result = 0;
    int num = 0;
    int sign = 1;
    for (int i = 0;
         i < s.size();
         i++) {
        char c = s[i];
        if (isdigit(c)) {
            num = 0;
            while (i < s.size() &&
                   isdigit(s[i])) {
                num =
                    num * 10 +
                    (s[i] - '0');
                i++;
            }
            i--;
            result += sign * num;
        }
        else if (c == '+') {
            sign = 1;
        }
        else if (c == '-') {
            sign = -1;
        }
        else if (c == '(') {
            st.push(result);
            st.push(sign);
            result = 0;
            sign = 1;
        }
        else if (c == ')') {
            int prevSign = st.top();
            st.pop();
            int prevResult = st.top();
            st.pop();
            result =
                prevResult +
                prevSign * result;
        }
    }
    return result;
}

string removeKdigits(
    string num,
    int k) {
    string st;
    for (char c : num) {
        while (!st.empty() &&
               k > 0 &&
               st.back() > c) {
            st.pop_back();
            k--;
        }
        st.push_back(c);
    }
    while (k > 0) {
        st.pop_back();
        k--;
    }
    int i = 0;
    while (i < st.size() &&
           st[i] == '0') {
        i++;
    }
    string ans = st.substr(i);
    return ans.empty() ? "0" : ans;
}

string decodeString(string s) {
    stack<int> counts;
    stack<string> strings;
    string curr;
    int num = 0;
    for (char c : s) {
        if (isdigit(c)) {
            num =
                num * 10 +
                (c - '0');
        }
        else if (c == '[') {
            counts.push(num);
            strings.push(curr);
            num = 0;
            curr = "";
        }
        else if (c == ']') {
            int k = counts.top();
            counts.pop();
            string prev =
                strings.top();
            strings.pop();
            while (k--)
                prev += curr;
            curr = prev;
        }
        else {
            curr += c;
        }
    }
    return curr;
}

vector<int> asteroidCollision(
    vector<int>& asteroids) {
    vector<int> st;
    for (int x : asteroids) {
        bool alive = true;
        while (alive &&
               x < 0 &&
               !st.empty() &&
               st.back() > 0) {
            if (st.back() < -x) {
                st.pop_back();
            }
            else if (st.back() == -x) {
                st.pop_back();
                alive = false;
            }
            else {
                alive = false;
            }
        }
        if (alive)
            st.push_back(x);
    }
    return st;
}

int trap(vector<int>& height) {
    int n = height.size();
    stack<int> st;
    int water = 0;
    for (int i = 0; i < n; i++) {
        while (!st.empty() &&
               height[i] >
               height[st.top()]) {
            int bottom = st.top();
            st.pop();
            if (st.empty())
                break;
            int left = st.top();
            int width =
                i - left - 1;
            int h =
                min(height[left],
                    height[i])
                - height[bottom];
            water += width * h;
        }
        st.push(i);
    }
    return water;
}

