            st.pop();
        }
        st.push({
            price,
            span
        });
        return span;
    }
};

class MyQueue {
    stack<int> in;
    stack<int> out;
public:
    void push(int x) {
        in.push(x);
    }
    int pop() {
        shift();
        int x = out.top();
        out.pop();
        return x;
    }
    int peek() {
        shift();
        return out.top();
    }
    bool empty() {
        return in.empty() &&
               out.empty();
    }
private:
    void shift() {
        if (out.empty()) {
            while (!in.empty()) {
                out.push(in.top());
                in.pop();
            }
        }
    }
};

void heapify(vector<int>& arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < n && arr[left] > arr[largest])
        largest = left;
    if (right < n && arr[right] > arr[largest])
        largest = right;
    if (largest != i) {
        swap(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}

void buildHeap(vector<int>& arr) {
    int n = arr.size();
    for (int i = n / 2 - 1; i >= 0; i--)
        heapify(arr, n, i);
}

void insertHeap(vector<int>& heap, int val) {
    heap.push_back(val);
    int i = heap.size() - 1;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] >= heap[i])
            break;
        swap(heap[parent], heap[i]);
        i = parent;
    }
}

int extractMax(vector<int>& heap) {
    if (heap.empty())
        return -1;
    int ans = heap[0];
    heap[0] = heap.back();
    heap.pop_back();
    if (!heap.empty())
        heapify(heap, heap.size(), 0);
    return ans;
}

