class MedianFinder {
    priority_queue<int> left;
    priority_queue<
        int,
        vector<int>,
        greater<int>
    > right;
public:
    void addNum(int num) {
        if (left.empty() ||
            num <= left.top()) {
            left.push(num);
        }
        else {
            right.push(num);
        }
        if (left.size() >
            right.size() + 1) {
            right.push(left.top());
            left.pop();
        }
        else if (right.size() >
                 left.size()) {
            left.push(right.top());
            right.pop();
        }
    }
    double findMedian() {
        if (left.size() ==
            right.size()) {
            return (
                (double)left.top() +
                right.top()
            ) / 2.0;
        }
        return left.top();
    }
};

vector<double> medianSlidingWindow(
    vector<int>& nums,
    int k) {
    multiset<int> low, high;
    auto balance = [&]() {
        while (low.size() > high.size() + 1) {
            auto it = prev(low.end());
            high.insert(*it);
            low.erase(it);
        }
        while (low.size() < high.size()) {
            auto it = high.begin();
            low.insert(*it);
            high.erase(it);
        }
    };
    auto add = [&](int x) {
        if (low.empty() ||
            x <= *prev(low.end()))
            low.insert(x);
        else
            high.insert(x);
        balance();
    };
    auto remove = [&](int x) {
        auto it = low.find(x);
        if (it != low.end())
            low.erase(it);
        else {
            it = high.find(x);
            high.erase(it);
        }
        balance();
    };
    vector<double> ans;
    for (int i = 0;
         i < nums.size();
         i++) {
        add(nums[i]);
        if (i >= k)
            remove(nums[i - k]);
        if (i >= k - 1) {
            if (low.size() == high.size()) {
                ans.push_back(
                    ((double)*prev(low.end()) +
                     *high.begin()) / 2.0
                );
            }
            else {
                ans.push_back(
                    *prev(low.end())
                );
            }
        }
    }
    return ans;
}

vector<int> mergeKSortedArrays(
    vector<vector<int>>& arr) {
    using T = tuple<int, int, int>;
    priority_queue<
        T,
        vector<T>,
        greater<T>
    > pq;
    for (int i = 0;
         i < arr.size();
         i++) {
        if (!arr[i].empty())
            pq.push({arr[i][0], i, 0});
    }
    vector<int> ans;
    while (!pq.empty()) {
        auto [val, row, col] =
            pq.top();
        pq.pop();
        ans.push_back(val);
        if (col + 1 < arr[row].size()) {
            pq.push({
                arr[row][col + 1],
                row,
                col + 1
            });
        }
    }
    return ans;
}

