    while (pq.size() > 1) {
        int a = pq.top();
        pq.pop();
        int b = pq.top();
        pq.pop();
        int sum = a + b;
        cost += sum;
        pq.push(sum);
    }
    return cost;
}

struct HuffmanNode {
    char ch;
    int freq;
    HuffmanNode* left;
    HuffmanNode* right;
    HuffmanNode(
        char ch,
        int freq)
        : ch(ch),
          freq(freq),
          left(nullptr),
          right(nullptr) {}
};
struct CompareHuffman {
    bool operator()(
        HuffmanNode* a,
        HuffmanNode* b) {
        return a->freq > b->freq;
    }
};
HuffmanNode* buildHuffman(
    vector<pair<char, int>>& freq) {
    priority_queue<
        HuffmanNode*,
        vector<HuffmanNode*>,
        CompareHuffman
    > pq;
    for (auto& [ch, f] : freq)
        pq.push(
            new HuffmanNode(ch, f)
        );
    while (pq.size() > 1) {
        HuffmanNode* a = pq.top();
        pq.pop();
        HuffmanNode* b = pq.top();
        pq.pop();
        HuffmanNode* parent =
            new HuffmanNode(
                '\0',
                a->freq + b->freq
            );
        parent->left = a;
        parent->right = b;
        pq.push(parent);
    }
    return pq.top();
}

vector<vector<int>> kSmallestPairs(
