        int,
        int
    >;
    priority_queue<
        T,
        vector<T>,
        greater<T>
    > pq;
    int n = min(
        (int)nums1.size(),
        k
    );
    for (int i = 0; i < n; i++) {
        pq.push({
            (long long)nums1[i] +
            nums2[0],
            i,
            0
        });
    }
    vector<vector<int>> ans;
    while (k-- && !pq.empty()) {
        auto [sum, i, j] =
            pq.top();
        pq.pop();
        ans.push_back({
            nums1[i],
            nums2[j]
        });
        if (j + 1 < nums2.size()) {
            pq.push({
                (long long)nums1[i] +
                nums2[j + 1],
                i,
                j + 1
            });
        }
    }
    return ans;
}

int countPairs(
    vector<int>& nums,
    int maxDist) {
    int count = 0;
    int left = 0;
    for (int right = 0;
         right < nums.size();
         right++) {
        while (
            nums[right] -
            nums[left] > maxDist
        ) {
            left++;
        }
        count += right - left;
    }
    return count;
}
int smallestDistancePair(
    vector<int>& nums,
    int k) {
    sort(
        nums.begin(),
        nums.end()
    );
    int left = 0;
    int right =
        nums.back() - nums.front();
    while (left < right) {
        int mid =
            left + (right - left) / 2;
        if (countPairs(nums, mid) >= k)
            right = mid;
        else
            left = mid + 1;
    }
    return left;
}

class RunningMedian {
    priority_queue<int> left;
    priority_queue<
        int,
        vector<int>,
        greater<int>
    > right;
public:
    double add(int x) {
        if (left.empty() ||
            x <= left.top())
            left.push(x);
        else
            right.push(x);
        if (left.size() >
            right.size() + 1) {
            right.push(left.top());
            left.pop();
        }
        if (right.size() >
            left.size()) {
            left.push(right.top());
            right.pop();
        }
        if (left.size() ==
            right.size()) {
            return (
                (double)left.top() +
                right.top()
            ) / 2;
        }
        return left.top();
    }
};

int findMaximizedCapital(
    int k,
    int w,
    vector<int>& profits,
    vector<int>& capital) {
    vector<pair<int, int>> projects;
    for (int i = 0;
         i < profits.size();
         i++) {
        projects.push_back({
            capital[i],
            profits[i]
        });
    }
    sort(
        projects.begin(),
        projects.end()
    );
    priority_queue<int> pq;
    int i = 0;
    while (k--) {
        while (
            i < projects.size() &&
            projects[i].first <= w
        ) {
            pq.push(projects[i].second);
            i++;
        }
        if (pq.empty())
            break;
        w += pq.top();
        pq.pop();
    }
    return w;
}

