int longestZeroSumSubarray(vector<int>& arr) {
    unordered_map<long long, int> mp;
    long long sum = 0;
    int ans = 0;
    mp[0] = -1;
    for (int i = 0; i < arr.size(); i++) {
        sum += arr[i];
        if (mp.count(sum)) {
            ans = max(ans, i - mp[sum]);
        } else {
            mp[sum] = i;
        }
    }
    return ans;
}

long long subarraySum(vector<int>& arr, int k) {
    unordered_map<long long, long long> freq;
    freq[0] = 1;
    long long sum = 0;
    long long ans = 0;
    for (int x : arr) {
        sum += x;
        if (freq.count(sum - k))
            ans += freq[sum - k];
        freq[sum]++;
    }
    return ans;
}

int findMaxLength(vector<int>& nums) {
    unordered_map<int, int> first;
    first[0] = -1;
    int sum = 0;
    int ans = 0;
    for (int i = 0; i < nums.size(); i++) {
        sum += (nums[i] == 1 ? 1 : -1);
        if (first.count(sum)) {
            ans = max(ans, i - first[sum]);
        } else {
            first[sum] = i;
        }
    }
    return ans;
}

Idea: Track (count0-count1, count1-count2) as the hash key.
int longestEqual012(vector<int>& arr) {
    map<pair<int, int>, int> first;
    int c0 = 0, c1 = 0, c2 = 0;
    int ans = 0;
    first[{0, 0}] = -1;
    for (int i = 0; i < arr.size(); i++) {
        if (arr[i] == 0) c0++;
        else if (arr[i] == 1) c1++;
        else c2++;
        pair<int, int> key = {c0 - c1, c1 - c2};
        if (first.count(key)) {
            ans = max(ans, i - first[key]);
        } else {
            first[key] = i;
        }
    }
    return ans;
}

int longestConsecutive(vector<int>& nums) {
    unordered_set<int> st(nums.begin(), nums.end());
    int ans = 0;
    for (int x : st) {
        if (!st.count(x - 1)) {
            int curr = x;
            int len = 1;
            while (st.count(curr + 1)) {
                curr++;
                len++;
            }
            ans = max(ans, len);
        }
    }
