}

long long countPairsDifference(vector<int>& arr, int k) {
    unordered_map<int, long long> freq;
    long long ans = 0;
    for (int x : arr) {
        ans += freq[x - k];
        if (k != 0)
            ans += freq[x + k];
        freq[x]++;
