vector<int> countDistinct(vector<int>& arr, int k) {
    unordered_map<int, int> freq;
    vector<int> ans;
    for (int i = 0; i < k; i++)
        freq[arr[i]]++;
    ans.push_back(freq.size());
    for (int i = k; i < arr.size(); i++) {
        freq[arr[i]]++;
        freq[arr[i - k]]--;
        if (freq[arr[i - k]] == 0)
            freq.erase(arr[i - k]);
        ans.push_back(freq.size());
    }
    return ans;
}

vector<pair<int, int>> findPairs(vector<int>& arr, int k) {
