long long countXorSubarrays(vector<int>& arr, int k) {
    unordered_map<int, long long> freq;
    freq[0] = 1;
    int xr = 0;
    long long ans = 0;
    for (int x : arr) {
        xr ^= x;
        ans += freq[xr ^ k];
        freq[xr]++;
    }
    return ans;
