int longestXorSubarray(vector<int>& arr, int k) {
    unordered_map<int, int> first;
    first[0] = -1;
    int xr = 0;
    int ans = 0;
    for (int i = 0; i < arr.size(); i++) {
        xr ^= arr[i];
        int required = xr ^ k;
        if (first.count(required))
            ans = max(ans, i - first[required]);
        if (!first.count(xr))
            first[xr] = i;
    }
    return ans;
}

bool sameSubarraySum(vector<int>& a, vector<int>& b) {
