    first[0] = -1;
    long long sum = 0;
    int ans = 0;
    for (int i = 0; i < arr.size(); i++) {
        sum += arr[i];
        int rem = ((sum % k) + k) % k;
        if (first.count(rem)) {
            ans = max(ans, i - first[rem]);
        } else {
            first[rem] = i;
        }
    }
    return ans;
}

struct PairHash {
