struct VectorHash {
    size_t operator()(const vector<int>& v) const {
        size_t hash = 0;
        for (int x : v) {
            hash ^= std::hash<int>()(x)
                    + 0x9e3779b9
                    + (hash << 6)
                    + (hash >> 2);
        }
        return hash;
    }
};
