vector<int> twoSum(vector<int>& nums, int target) {
    int l = 0, r = nums.size() - 1;
    while (l < r) {
        long long sum = nums[l] + nums[r];
        if (sum == target)
            return {l, r};
        if (sum < target)
            l++;
        else
            r--;
    }
    return {};
}
Time Complexity: O(n)
Space Complexity: O(1).

vector<vector<int>> threeSum(vector<int>& nums) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> ans;
    int n = nums.size();
    for (int i = 0; i < n - 2; i++) {
        if (i > 0 && nums[i] == nums[i - 1])
            continue;
        int l = i + 1;
        int r = n - 1;
        while (l < r) {
            long long sum = 1LL * nums[i] + nums[l] + nums[r];
            if (sum == 0) {
                ans.push_back({nums[i], nums[l], nums[r]});
                int x = nums[l];
                int y = nums[r];
                while (l < r && nums[l] == x) l++;
                while (l < r && nums[r] == y) r--;
            }
            else if (sum < 0)
                l++;
            else
                r--;
        }
    }
    return ans;
}
Time Complexity: O(n²)
Space Complexity: O(1) excluding output.

vector<vector<int>> fourSum(vector<int>& nums, long long target) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> ans;
    int n = nums.size();
    for (int i = 0; i < n - 3; i++) {
        if (i > 0 && nums[i] == nums[i - 1])
            continue;
        for (int j = i + 1; j < n - 2; j++) {
            if (j > i + 1 && nums[j] == nums[j - 1])
                continue;
            int l = j + 1;
            int r = n - 1;
            while (l < r) {
                long long sum = 1LL * nums[i] + nums[j]
                              + nums[l] + nums[r];
                if (sum == target) {
                    ans.push_back({
                        nums[i], nums[j], nums[l], nums[r]
                    });
                    int x = nums[l];
                    int y = nums[r];
                    while (l < r && nums[l] == x) l++;
                    while (l < r && nums[r] == y) r--;
                }
                else if (sum < target)
                    l++;
                else
                    r--;
            }
        }
    }
    return ans;
}
Time Complexity: O(n³)
Space Complexity: O(1) excluding output.

