string minWindow(string s, string t) {
    vector<int> need(256, 0);
    for (char c : t)
        need[c]++;
    int required = t.size();
    int l = 0;
    int bestLen = INT_MAX;
    int bestL = 0;
    for (int r = 0; r < s.size(); r++) {
        if (need[s[r]] > 0)
            required--;
        need[s[r]]--;
        while (required == 0) {
            if (r - l + 1 < bestLen) {
                bestLen = r - l + 1;
                bestL = l;
            }
            need[s[l]]++;
            if (need[s[l]] > 0)
                required++;
            l++;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestL, bestLen);
}
Time Complexity: O(n + m)
Space Complexity: O(1).

int characterReplacement(string s, int k) {
    vector<int> freq(26, 0);
    int l = 0;
    int maxFreq = 0;
    int ans = 0;
    for (int r = 0; r < s.size(); r++) {
        freq[s[r] - 'A']++;
        maxFreq = max(maxFreq, freq[s[r] - 'A']);
        while ((r - l + 1) - maxFreq > k) {
            freq[s[l] - 'A']--;
            l++;
        }
        ans = max(ans, r - l + 1);
    }
    return ans;
}
Time Complexity: O(n)
Space Complexity: O(1).

bool checkInclusion(string s1, string s2) {
    if (s1.size() > s2.size())
        return false;
    vector<int> need(26, 0);
    vector<int> have(26, 0);
    for (char c : s1)
        need[c - 'a']++;
    int k = s1.size();
    for (int i = 0; i < s2.size(); i++) {
        have[s2[i] - 'a']++;
        if (i >= k)
            have[s2[i - k] - 'a']--;
        if (have == need)
            return true;
    }
    return false;
}
Time Complexity: O(n * 26) → effectively O(n)
Space Complexity: O(1).

vector<int> findAnagrams(string s, string p) {
    vector<int> need(26, 0);
    vector<int> have(26, 0);
    for (char c : p)
        need[c - 'a']++;
    vector<int> ans;
    int k = p.size();
    for (int i = 0; i < s.size(); i++) {
        have[s[i] - 'a']++;
        if (i >= k)
            have[s[i - k] - 'a']--;
        if (i >= k - 1 && have == need)
            ans.push_back(i - k + 1);
    }
    return ans;
}
Time Complexity: O(n * 26) → effectively O(n)
Space Complexity: O(1).

int maxArea(vector<int>& height) {
    int l = 0;
    int r = height.size() - 1;
    int ans = 0;
    while (l < r) {
        int area = min(height[l], height[r]) * (r - l);
        ans = max(ans, area);
        if (height[l] < height[r])
            l++;
        else
            r--;
    }
    return ans;
}
Time Complexity: O(n)
Space Complexity: O(1).

int trap(vector<int>& height) {
    int l = 0;
    int r = height.size() - 1;
    int leftMax = 0;
    int rightMax = 0;
    int ans = 0;
    while (l < r) {
        if (height[l] <= height[r]) {
            if (height[l] >= leftMax)
                leftMax = height[l];
            else
                ans += leftMax - height[l];
            l++;
        }
        else {
            if (height[r] >= rightMax)
                rightMax = height[r];
            else
                ans += rightMax - height[r];
            r--;
        }
    }
    return ans;
}
Time Complexity: O(n)
Space Complexity: O(1).

int numSubarrayProductLessThanK(vector<int>& nums, int k) {
