        return 0;
    long long product = 1;
    int l = 0;
    int ans = 0;
    for (int r = 0; r < nums.size(); r++) {
        product *= nums[r];
        while (product >= k)
            product /= nums[l++];
        ans += r - l + 1;
    }
    return ans;
}
