int minSwaps(vector<int>& nums) {
    int k = accumulate(nums.begin(), nums.end(), 0);
    if (k <= 1)
        return 0;
    int ones = 0;
    for (int i = 0; i < k; i++)
        ones += nums[i];
    int maxOnes = ones;
    for (int i = k; i < nums.size(); i++) {
        ones += nums[i];
        ones -= nums[i - k];
        maxOnes = max(maxOnes, ones);
    }
    return k - maxOnes;
}
Time Complexity: O(n)
Space Complexity: O(1).

