vector<long long> rangeAddition(
    int n,
    vector<vector<int>>& updates
) {
    vector<long long> diff(n + 1, 0);
    for (auto& q : updates) {
        int l = q[0];
        int r = q[1];
        int x = q[2];
        diff[l] += x;
        if (r + 1 < n)
            diff[r + 1] -= x;
    }
    vector<long long> arr(n);
    long long curr = 0;
    for (int i = 0; i < n; i++) {
        curr += diff[i];
        arr[i] = curr;
    }
    return arr;
}

vector<int> activeIntervals(
    int n,
    vector<pair<int, int>>& intervals
) {
    vector<int> diff(n + 1, 0);
    for (auto [l, r] : intervals) {
        diff[l]++;
        if (r + 1 < n)
            diff[r + 1]--;
    }
    vector<int> ans(n);
    int curr = 0;
    for (int i = 0; i < n; i++) {
        curr += diff[i];
        ans[i] = curr;
    }
    return ans;
}

vector<vector<long long>> buildPrefix(
    vector<vector<int>>& mat
) {
    int n = mat.size();
    int m = mat[0].size();
    vector<vector<long long>> pref(
        n + 1,
        vector<long long>(m + 1, 0)
    );
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            pref[i][j] =
                mat[i - 1][j - 1]
                + pref[i - 1][j]
                + pref[i][j - 1]
                - pref[i - 1][j - 1];
        }
    }
    return pref;
}
long long query(
    vector<vector<long long>>& pref,
    int r1, int c1,
    int r2, int c2
) {
    r1++;
    c1++;
    r2++;
    c2++;
    return pref[r2][c2]
         - pref[r1 - 1][c2]
         - pref[r2][c1 - 1]
         + pref[r1 - 1][c1 - 1];
}
Build Time: O(n × m)
Query Time: O(1)
Space: O(n × m)

vector<vector<long long>> rectangleUpdates(
    int n,
    int m,
    vector<vector<int>>& queries
) {
    vector<vector<long long>> diff(
        n + 1,
        vector<long long>(m + 1, 0)
    );
    for (auto& q : queries) {
        int r1 = q[0];
        int c1 = q[1];
        int r2 = q[2];
        int c2 = q[3];
        int val = q[4];
        diff[r1][c1] += val;
        if (r2 + 1 < n)
            diff[r2 + 1][c1] -= val;
        if (c2 + 1 < m)
            diff[r1][c2 + 1] -= val;
        if (r2 + 1 < n && c2 + 1 < m)
            diff[r2 + 1][c2 + 1] += val;
    }
    vector<vector<long long>> ans(
        n,
        vector<long long>(m)
    );
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i > 0)
                diff[i][j] += diff[i - 1][j];
            if (j > 0)
                diff[i][j] += diff[i][j - 1];
            if (i > 0 && j > 0)
                diff[i][j] -= diff[i - 1][j - 1];
            ans[i][j] = diff[i][j];
        }
    }
    return ans;
}

long long maxSubarraySum(vector<int>& arr) {
    long long sum = 0;
    long long minPrefix = 0;
    long long ans = LLONG_MIN;
    for (int x : arr) {
        sum += x;
        ans = max(ans, sum - minPrefix);
        minPrefix = min(minPrefix, sum);
    }
    return ans;
}

long long maxSumAtMostK(vector<int>& arr, int k) {
    int n = arr.size();
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++)
        pref[i + 1] = pref[i] + arr[i];
    deque<int> dq;
    long long ans = LLONG_MIN;
    for (int i = 1; i <= n; i++) {
        while (!dq.empty() && dq.front() < i - k)
            dq.pop_front();
        if (!dq.empty())
            ans = max(ans, pref[i] - pref[dq.front()]);
        while (!dq.empty() && pref[dq.back()] >= pref[i])
            dq.pop_back();
        dq.push_back(i);
    }
    return ans;
}

long long maxSumRangeLength(
    vector<int>& arr,
    int L,
    int R
) {
    int n = arr.size();
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++)
        pref[i + 1] = pref[i] + arr[i];
    deque<int> dq;
    long long ans = LLONG_MIN;
    for (int i = L; i <= n; i++) {
        int add = i - L;
        while (!dq.empty() &&
               pref[dq.back()] >= pref[add])
            dq.pop_back();
        dq.push_back(add);
        while (!dq.empty() &&
               dq.front() < i - R)
            dq.pop_front();
        ans = max(ans, pref[i] - pref[dq.front()]);
    }
    return ans;
}

long long countXorK(vector<int>& arr, int k) {
    unordered_map<int, long long> freq;
    freq[0] = 1;
    int xr = 0;
    long long ans = 0;
    for (int x : arr) {
        xr ^= x;
        ans += freq[xr ^ k];
        freq[xr]++;
    }
    return ans;
}

