}

vector<long long> compressedPrefix(
    vector<pair<long long, long long>>& points
) {
    vector<long long> coords;
    for (auto [x, val] : points)
        coords.push_back(x);
    sort(coords.begin(), coords.end());
    coords.erase(
        unique(coords.begin(), coords.end()),
        coords.end()
    );
    vector<long long> pref(coords.size() + 1, 0);
    for (auto [x, val] : points) {
        int idx = lower_bound(
            coords.begin(),
            coords.end(),
            x
        ) - coords.begin();
        pref[idx + 1] += val;
    }
    for (int i = 1; i < pref.size(); i++)
        pref[i] += pref[i - 1];
    return pref;
}

vector<int> prefixMin(vector<int>& arr) {
    int n = arr.size();
    vector<int> pref(n);
    pref[0] = arr[0];
    for (int i = 1; i < n; i++)
        pref[i] = min(pref[i - 1], arr[i]);
    return pref;
}

int maximumOverlap(
    int n,
    vector<pair<int, int>>& intervals
) {
    vector<int> diff(n + 2, 0);
    for (auto [l, r] : intervals) {
        diff[l]++;
        diff[r + 1]--;
    }
    int curr = 0;
    int ans = 0;
    for (int i = 0; i <= n; i++) {
        curr += diff[i];
        ans = max(ans, curr);
    }
    return ans;
}

int activitySelection(vector<pair<int, int>>& activities) {
    sort(activities.begin(), activities.end(),
         [](auto& a, auto& b) {
             return a.second < b.second;
         });
    int ans = 0;
    int lastEnd = -1;
    for (auto& [start, end] : activities) {
        if (start >= lastEnd) {
            ans++;
            lastEnd = end;
        }
    }
    return ans;
}
Time Complexity: O(n log n)
Space Complexity: O(1) excluding sorting.

double fractionalKnapsack(vector<int>& wt, vector<int>& val, int W) {
    int n = wt.size();
    vector<pair<double, int>> items;
    for (int i = 0; i < n; i++) {
        items.push_back({(double)val[i] / wt[i], i});
    }
    sort(items.rbegin(), items.rend());
    double ans = 0;
    for (auto& [ratio, i] : items) {
        if (W == 0) break;
        int take = min(W, wt[i]);
        ans += take * ratio;
        W -= take;
    }
    return ans;
}
Time Complexity: O(n log n)
Space Complexity: O(n).

vector<int> jobSequencing(vector<pair<int, int>>& jobs) {
    // {deadline, profit}
    sort(jobs.begin(), jobs.end(),
         [](auto& a, auto& b) {
             return a.second > b.second;
         });
    int maxDeadline = 0;
    for (auto& [deadline, profit] : jobs)
        maxDeadline = max(maxDeadline, deadline);
    vector<int> slot(maxDeadline + 1, -1);
    int count = 0, profit = 0;
    for (int i = 0; i < jobs.size(); i++) {
        int deadline = jobs[i].first;
        int value = jobs[i].second;
        for (int t = min(deadline, maxDeadline); t >= 1; t--) {
            if (slot[t] == -1) {
                slot[t] = i;
                count++;
                profit += value;
                break;
            }
        }
    }
    return {count, profit};
}
Time Complexity: O(n log n + nD) where D is maximum deadline.
Space Complexity: O(D).

int minPlatforms(vector<int>& arrival, vector<int>& departure) {
    sort(arrival.begin(), arrival.end());
    sort(departure.begin(), departure.end());
    int i = 0, j = 0;
    int curr = 0, ans = 0;
    int n = arrival.size();
    while (i < n && j < n) {
        if (arrival[i] <= departure[j]) {
            curr++;
            ans = max(ans, curr);
            i++;
        } else {
            curr--;
            j++;
        }
    }
    return ans;
}
Time Complexity: O(n log n)
Space Complexity: O(1) excluding sorting.

bool canJump(vector<int>& nums) {
    int farthest = 0;
    for (int i = 0; i < nums.size(); i++) {
        if (i > farthest)
            return false;
        farthest = max(farthest, i + nums[i]);
    }
    return true;
}
Time Complexity: O(n)
Space Complexity: O(1).

int jump(vector<int>& nums) {
    int jumps = 0;
    int currentEnd = 0;
    int farthest = 0;
    for (int i = 0; i < nums.size() - 1; i++) {
        farthest = max(farthest, i + nums[i]);
        if (i == currentEnd) {
            jumps++;
            currentEnd = farthest;
        }
    }
    return jumps;
}
Time Complexity: O(n)
Space Complexity: O(1).

int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
    int total = 0;
    int tank = 0;
    int start = 0;
    for (int i = 0; i < gas.size(); i++) {
        int diff = gas[i] - cost[i];
        total += diff;
        tank += diff;
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }
    return total >= 0 ? start : -1;
}
Time Complexity: O(n)
Space Complexity: O(1).

int candy(vector<int>& ratings) {
    int n = ratings.size();
    vector<int> candies(n, 1);
    for (int i = 1; i < n; i++) {
        if (ratings[i] > ratings[i - 1])
            candies[i] = candies[i - 1] + 1;
    }
    for (int i = n - 2; i >= 0; i--) {
        if (ratings[i] > ratings[i + 1])
            candies[i] = max(candies[i], candies[i + 1] + 1);
    }
    return accumulate(candies.begin(), candies.end(), 0);
}
Time Complexity: O(n)
Space Complexity: O(n).

vector<int> partitionLabels(string s) {
    vector<int> last(26, 0);
    for (int i = 0; i < s.size(); i++)
        last[s[i] - 'a'] = i;
    vector<int> ans;
    int start = 0;
    int end = 0;
    for (int i = 0; i < s.size(); i++) {
        end = max(end, last[s[i] - 'a']);
        if (i == end) {
            ans.push_back(end - start + 1);
            start = i + 1;
        }
    }
    return ans;
}
Time Complexity: O(n)
Space Complexity: O(1).

int eraseOverlapIntervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end(),
         [](auto& a, auto& b) {
             return a[1] < b[1];
         });
    int removed = 0;
    int lastEnd = INT_MIN;
    for (auto& interval : intervals) {
        if (interval[0] < lastEnd) {
            removed++;
        } else {
            lastEnd = interval[1];
        }
    }
    return removed;
}
Time Complexity: O(n log n)
Space Complexity: O(1) excluding sorting.

int findMinArrowShots(vector<vector<int>>& points) {
    if (points.empty()) return 0;
    sort(points.begin(), points.end(),
         [](auto& a, auto& b) {
             return a[1] < b[1];
         });
    int arrows = 1;
    long long pos = points[0][1];
    for (int i = 1; i < points.size(); i++) {
        if (points[i][0] > pos) {
            arrows++;
            pos = points[i][1];
        }
    }
    return arrows;
}
Time Complexity: O(n log n)
Space Complexity: O(1) excluding sorting.

long long huffmanCost(vector<int>& freq) {
    priority_queue<long long,
                   vector<long long>,
                   greater<long long>> pq;
    for (int x : freq)
        pq.push(x);
    long long cost = 0;
    while (pq.size() > 1) {
        long long a = pq.top();
        pq.pop();
        long long b = pq.top();
        pq.pop();
        long long sum = a + b;
        cost += sum;
        pq.push(sum);
    }
    return cost;
}
Time Complexity: O(n log n)
Space Complexity: O(n).

