int leastInterval(vector<char>& tasks, int n) {
    vector<int> freq(26, 0);
    for (char c : tasks)
        freq[c - 'A']++;
    int maxFreq = *max_element(freq.begin(), freq.end());
    int maxCount = 0;
    for (int f : freq) {
        if (f == maxFreq)
            maxCount++;
    }
    int slots = (maxFreq - 1) * (n + 1) + maxCount;
    return max((int)tasks.size(), slots);
}
Time Complexity: O(n + 26)
Space Complexity: O(1).

int minMeetingRooms(vector<vector<int>>& intervals) {
    vector<int> start, finish;
    for (auto& x : intervals) {
        start.push_back(x[0]);
        finish.push_back(x[1]);
    }
    sort(start.begin(), start.end());
    sort(finish.begin(), finish.end());
    int i = 0, j = 0;
    int rooms = 0;
    int ans = 0;
    while (i < start.size()) {
        if (start[i] < finish[j]) {
            rooms++;
            ans = max(ans, rooms);
            i++;
        } else {
            rooms--;
            j++;
        }
    }
    return ans;
}
Time Complexity: O(n log n)
Space Complexity: O(n).

string removeKdigits(string num, int k) {
    string st;
    for (char c : num) {
        while (!st.empty() && k > 0 && st.back() > c) {
            st.pop_back();
            k--;
        }
        st.push_back(c);
    }
    while (k > 0) {
        st.pop_back();
        k--;
    }
    int i = 0;
    while (i < st.size() && st[i] == '0')
        i++;
    string ans = st.substr(i);
    return ans.empty() ? "0" : ans;
}
Time Complexity: O(n)
Space Complexity: O(n).

int gasStation(vector<int>& gas, vector<int>& cost) {
    int total = 0;
    int tank = 0;
    int start = 0;
    for (int i = 0; i < gas.size(); i++) {
        tank += gas[i] - cost[i];
        total += gas[i] - cost[i];
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }
    return total >= 0 ? start : -1;
}
Time Complexity: O(n)
Space Complexity: O(1).

int findContentChildren(vector<int>& g, vector<int>& s) {
    sort(g.begin(), g.end());
    sort(s.begin(), s.end());
    int i = 0;
    for (int cookie : s) {
        if (i < g.size() && cookie >= g[i])
            i++;
    }
    return i;
}
Time Complexity: O(n log n + m log m)
Space Complexity: O(1) excluding sorting.

int numRescueBoats(vector<int>& people, int limit) {
    sort(people.begin(), people.end());
    int l = 0;
    int r = people.size() - 1;
    int boats = 0;
    while (l <= r) {
        if (people[l] + people[r] <= limit)
            l++;
        r--;
        boats++;
    }
    return boats;
}
Time Complexity: O(n log n)
Space Complexity: O(1) excluding sorting.

int maxEvents(vector<vector<int>>& events) {
    sort(events.begin(), events.end());
    priority_queue<int,
                   vector<int>,
                   greater<int>> pq;
    int day = 0;
    int i = 0;
    int ans = 0;
    while (i < events.size() || !pq.empty()) {
        if (pq.empty())
            day = events[i][0];
        while (i < events.size() && events[i][0] <= day) {
            pq.push(events[i][1]);
            i++;
        }
        while (!pq.empty() && pq.top() < day)
            pq.pop();
        if (!pq.empty()) {
            pq.pop();
            ans++;
            day++;
        }
    }
    return ans;
}
Time Complexity: O(n log n)
Space Complexity: O(n).

void solve(int idx, vector<int>& arr, vector<int>& curr,
           vector<vector<int>>& ans) {
    if (idx == arr.size()) {
        ans.push_back(curr);
        return;
    }
    // Take
    curr.push_back(arr[idx]);
    solve(idx + 1, arr, curr, ans);
    curr.pop_back();
    // Don't take
    solve(idx + 1, arr, curr, ans);
}
vector<vector<int>> subsets(vector<int>& arr) {
    vector<vector<int>> ans;
