}

void solve(int start, vector<int>& arr, vector<int>& curr,
           vector<vector<int>>& ans) {
    ans.push_back(curr);
    for (int i = start; i < arr.size(); i++) {
        if (i > start && arr[i] == arr[i - 1])
            continue;
        curr.push_back(arr[i]);
        solve(i + 1, arr, curr, ans);
        curr.pop_back();
    }
}
