}

void solve(vector<int>& arr, vector<bool>& used,
           vector<int>& curr, vector<vector<int>>& ans) {
    if (curr.size() == arr.size()) {
        ans.push_back(curr);
        return;
    }
    for (int i = 0; i < arr.size(); i++) {
        if (used[i])
            continue;
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1])
            continue;
        used[i] = true;
        curr.push_back(arr[i]);
        solve(arr, used, curr, ans);
        curr.pop_back();
        used[i] = false;
    }
}
