    solve(arr, used, curr, ans);
    return ans;
}

bool isSafe(int row, int col, vector<string>& board, int n) {
    for (int i = 0; i < row; i++) {
        if (board[i][col] == 'Q')
            return false;
    }
    for (int i = row - 1, j = col - 1;
         i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 'Q')
            return false;
    }
    for (int i = row - 1, j = col + 1;
         i >= 0 && j < n; i--, j++) {
        if (board[i][j] == 'Q')
            return false;
    }
    return true;
}
void solve(int row, vector<string>& board,
           vector<vector<string>>& ans, int n) {
    if (row == n) {
        ans.push_back(board);
        return;
    }
    for (int col = 0; col < n; col++) {
        if (!isSafe(row, col, board, n))
            continue;
        board[row][col] = 'Q';
        solve(row + 1, board, ans, n);
        board[row][col] = '.';
    }
}
vector<vector<string>> solveNQueens(int n) {
    vector<string> board(n, string(n, '.'));
    vector<vector<string>> ans;
    solve(0, board, ans, n);
    return ans;
}

void solve(int row, int n, int cols, int diag1, int diag2,
           long long& ans) {
    if (row == n) {
        ans++;
        return;
    }
    int available = ((1 << n) - 1) &
                    ~(cols | diag1 | diag2);
    while (available) {
        int bit = available & -available;
        available -= bit;
        solve(row + 1, n,
              cols | bit,
              (diag1 | bit) << 1,
              (diag2 | bit) >> 1,
              ans);
    }
}
long long totalNQueens(int n) {
