    solve(0, n, 0, 0, 0, ans);
    return ans;
}

void solve(int start, int target, vector<int>& arr,
           vector<int>& curr, vector<vector<int>>& ans) {
    if (target == 0) {
        ans.push_back(curr);
        return;
    }
    for (int i = start; i < arr.size(); i++) {
        if (arr[i] > target)
            break;
        curr.push_back(arr[i]);
        solve(i, target - arr[i],
              arr, curr, ans);
        curr.pop_back();
    }
}
