bool solve(vector<vector<char>>& board) {
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (board[r][c] != '.')
                continue;
            for (char d = '1'; d <= '9'; d++) {
                bool ok = true;
                for (int i = 0; i < 9; i++) {
                    if (board[r][i] == d ||
                        board[i][c] == d) {
                        ok = false;
                        break;
                    }
                }
                int sr = (r / 3) * 3;
                int sc = (c / 3) * 3;
                for (int i = sr; i < sr + 3 && ok; i++) {
                    for (int j = sc; j < sc + 3; j++) {
                        if (board[i][j] == d) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (!ok)
                    continue;
                board[r][c] = d;
                if (solve(board))
                    return true;
                board[r][c] = '.';
            }
            return false;
        }
    }
    return true;
}

void solve(int r, int c, vector<vector<int>>& maze,
           vector<vector<int>>& vis, string& path,
           vector<string>& ans) {
    int n = maze.size();
    if (r == n - 1 && c == n - 1) {
        ans.push_back(path);
        return;
    }
    int dr[] = {1, 0, 0, -1};
    int dc[] = {0, -1, 1, 0};
    char dir[] = {'D', 'L', 'R', 'U'};
    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];
        if (nr >= 0 && nr < n &&
            nc >= 0 && nc < n &&
            maze[nr][nc] &&
            !vis[nr][nc]) {
            vis[nr][nc] = 1;
            path.push_back(dir[k]);
            solve(nr, nc, maze, vis, path, ans);
            path.pop_back();
            vis[nr][nc] = 0;
        }
    }
}
vector<string> ratInMaze(vector<vector<int>>& maze) {
    int n = maze.size();
    vector<string> ans;
    if (!maze[0][0] || !maze[n - 1][n - 1])
        return ans;
    vector<vector<int>> vis(n, vector<int>(n, 0));
    string path;
    vis[0][0] = 1;
    solve(0, 0, maze, vis, path, ans);
    return ans;
}

bool dfs(int r, int c, int idx,
         vector<vector<char>>& board,
         string& word) {
    if (idx == word.size())
        return true;
    int n = board.size();
    int m = board[0].size();
    if (r < 0 || r >= n ||
        c < 0 || c >= m ||
        board[r][c] != word[idx])
        return false;
    char temp = board[r][c];
    board[r][c] = '#';
    bool found =
        dfs(r + 1, c, idx + 1, board, word) ||
        dfs(r - 1, c, idx + 1, board, word) ||
        dfs(r, c + 1, idx + 1, board, word) ||
        dfs(r, c - 1, idx + 1, board, word);
    board[r][c] = temp;
    return found;
}
bool exist(vector<vector<char>>& board, string word) {
    for (int i = 0; i < board.size(); i++) {
        for (int j = 0; j < board[0].size(); j++) {
            if (dfs(i, j, 0, board, word))
                return true;
        }
    }
    return false;
}

bool solve(int node, int n, int k,
           vector<vector<int>>& graph,
           vector<int>& color) {
    if (node == n)
        return true;
    for (int c = 1; c <= k; c++) {
        bool safe = true;
        for (int v = 0; v < n; v++) {
            if (graph[node][v] && color[v] == c) {
                safe = false;
                break;
            }
        }
        if (!safe)
            continue;
        color[node] = c;
        if (solve(node + 1, n, k, graph, color))
            return true;
        color[node] = 0;
    }
    return false;
}
bool graphColoring(vector<vector<int>>& graph, int k) {
    int n = graph.size();
    vector<int> color(n, 0);
    return solve(0, n, k, graph, color);
}

bool solve(int u, int count,
           vector<vector<int>>& graph,
           vector<bool>& used) {
    if (count == graph.size())
        return true;
    for (int v = 0; v < graph.size(); v++) {
        if (graph[u][v] && !used[v]) {
            used[v] = true;
            if (solve(v, count + 1, graph, used))
                return true;
            used[v] = false;
        }
    }
    return false;
}
bool hamiltonianPath(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<bool> used(n, false);
    for (int start = 0; start < n; start++) {
        used[start] = true;
        if (solve(start, 1, graph, used))
            return true;
        used[start] = false;
    }
    return false;
}

bool solve(int idx, vector<int>& arr,
           vector<int>& bucket, int target) {
    if (idx == arr.size()) {
        for (int x : bucket) {
            if (x != target)
                return false;
        }
        return true;
    }
    for (int i = 0; i < bucket.size(); i++) {
        if (bucket[i] + arr[idx] > target)
            continue;
        if (i > 0 && bucket[i] == bucket[i - 1])
            continue;
        bucket[i] += arr[idx];
        if (solve(idx + 1, arr, bucket, target))
            return true;
        bucket[i] -= arr[idx];
    }
    return false;
}
bool canPartitionKSubsets(vector<int>& arr, int k) {
    int sum = accumulate(arr.begin(), arr.end(), 0);
    if (sum % k != 0)
        return false;
    int target = sum / k;
    sort(arr.rbegin(), arr.rend());
    vector<int> bucket(k, 0);
    return solve(0, arr, bucket, target);
}

