TreeNode* lowestCommonAncestor(
    TreeNode* root,
    TreeNode* p,
    TreeNode* q) {
    if (root == nullptr ||
        root == p ||
        root == q) {
        return root;
    }
    TreeNode* left =
        lowestCommonAncestor(
            root->left, p, q);
    TreeNode* right =
        lowestCommonAncestor(
            root->right, p, q);
    if (left != nullptr &&
        right != nullptr) {
        return root;
    }
    return left != nullptr
           ? left
           : right;
}

TreeNode* lowestCommonAncestor(
    TreeNode* root,
    TreeNode* p,
    TreeNode* q) {
    while (root != nullptr) {
        if (p->val < root->val &&
            q->val < root->val) {
            root = root->left;
        }
        else if (p->val > root->val &&
                 q->val > root->val) {
            root = root->right;
        }
        else {
            return root;
        }
    }
    return nullptr;
}

class Solution {
    struct Info {
        bool isBST;
        int mn;
        int mx;
        int sum;
    };
    int ans = 0;
    Info solve(TreeNode* root) {
        if (root == nullptr) {
            return {
                true,
                INT_MAX,
                INT_MIN,
                0
            };
        }
        Info left =
            solve(root->left);
        Info right =
            solve(root->right);
        if (left.isBST &&
            right.isBST &&
            left.mx < root->val &&
            root->val < right.mn) {
            int sum =
                left.sum +
                right.sum +
                root->val;
            ans = max(ans, sum);
            return {
                true,
                min(left.mn, root->val),
                max(right.mx, root->val),
                sum
            };
        }
        return {
            false,
            0,
            0,
            0
        };
    }
public:
    int maxSumBST(TreeNode* root) {
        solve(root);
        return ans;
    }
};

class Codec {
public:
    void serializeHelper(
        TreeNode* root,
        string& s) {
        if (root == nullptr) {
            s += "#,";
            return;
        }
        s += to_string(root->val);
        s += ",";
        serializeHelper(
            root->left, s);
        serializeHelper(
            root->right, s);
    }
    string serialize(TreeNode* root) {
        string s;
        serializeHelper(root, s);
        return s;
    }
    TreeNode* deserializeHelper(
        stringstream& ss) {
        string token;
        getline(ss, token, ',');
        if (token == "#")
            return nullptr;
        TreeNode* root =
            new TreeNode(stoi(token));
        root->left =
            deserializeHelper(ss);
        root->right =
            deserializeHelper(ss);
        return root;
    }
    TreeNode* deserialize(
        string data) {
        stringstream ss(data);
        return deserializeHelper(ss);
    }
};

class Solution {
    unordered_map<int, int> pos;
    int preIndex = 0;
    TreeNode* build(
        vector<int>& preorder,
        int l,
        int r) {
        if (l > r)
            return nullptr;
        int value =
            preorder[preIndex++];
        TreeNode* root =
            new TreeNode(value);
        int mid = pos[value];
        root->left =
            build(preorder, l, mid - 1);
        root->right =
            build(preorder, mid + 1, r);
        return root;
    }
public:
    TreeNode* buildTree(
        vector<int>& preorder,
        vector<int>& inorder) {
        for (int i = 0;
             i < inorder.size();
             i++) {
            pos[inorder[i]] = i;
        }
        return build(
            preorder,
            0,
            inorder.size() - 1);
    }
};

class Solution {
    unordered_map<int, int> pos;
    int postIndex;
    TreeNode* build(
        vector<int>& postorder,
        int l,
        int r) {
        if (l > r)
            return nullptr;
        int value =
            postorder[postIndex--];
        TreeNode* root =
            new TreeNode(value);
        int mid = pos[value];
        root->right =
            build(
                postorder,
                mid + 1,
                r);
        root->left =
            build(
                postorder,
                l,
                mid - 1);
        return root;
    }
public:
    TreeNode* buildTree(
        vector<int>& inorder,
        vector<int>& postorder) {
        for (int i = 0;
             i < inorder.size();
             i++) {
            pos[inorder[i]] = i;
        }
        postIndex =
            postorder.size() - 1;
        return build(
            postorder,
            0,
            inorder.size() - 1);
    }
};

const int LOG = 20;
vector<vector<int>> up;
vector<int> depth;
void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj) {
    up[u][0] = parent;
    for (int j = 1; j < LOG; j++) {
        up[u][j] =
            up[
                up[u][j - 1]
            ][j - 1];
    }
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        depth[v] =
            depth[u] + 1;
        dfs(v, u, adj);
    }
}
int LCA(int u, int v) {
    if (depth[u] < depth[v])
        swap(u, v);
    int diff =
        depth[u] - depth[v];
    for (int j = LOG - 1;
         j >= 0;
         j--) {
        if (diff & (1 << j))
            u = up[u][j];
    }
    if (u == v)
        return u;
    for (int j = LOG - 1;
         j >= 0;
         j--) {
        if (up[u][j] != up[v][j]) {
            u = up[u][j];
            v = up[v][j];
        }
    }
    return up[u][0];
}
Preprocessing: O(n log n)
Each LCA query: O(log n)
Space: O(n log n)

int kthAncestor(
    int node,
    int k) {
    for (int j = 0;
         j < LOG;
         j++) {
        if (k & (1 << j))
            node = up[node][j];
        if (node == -1)
            break;
    }
    return node;
}

