vector<vector<int>> dp;
void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj) {
    // dp[u][0] = don't take u
    // dp[u][1] = take u
    dp[u][0] = 0;
    dp[u][1] = 1;
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        dfs(v, u, adj);
        dp[u][0] +=
            max(
                dp[v][0],
                dp[v][1]
            );
        dp[u][1] +=
            dp[v][0];
    }
}

vector<vector<int>> dp;
void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj) {
    // dp[u][0] = don't take u
    // dp[u][1] = take u
    dp[u][0] = 0;
    dp[u][1] = 1;
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        dfs(v, u, adj);
        // u not selected
        // child must be selected
        dp[u][0] +=
            dp[v][1];
        // u selected
        // child can be either
        dp[u][1] +=
            min(
                dp[v][0],
                dp[v][1]
            );
    }
}

