bool hasPathSum(
    TreeNode* root,
    int targetSum) {
    if (root == nullptr)
        return false;
    if (root->left == nullptr &&
        root->right == nullptr) {
        return targetSum == root->val;
    }
    targetSum -= root->val;
    return
        hasPathSum(
            root->left,
            targetSum)
        ||
        hasPathSum(
            root->right,
            targetSum);
}

void dfs(
