        depth[v] =
            depth[u] + 1;
        dfs(v, u, adj);
        subtree[u] += subtree[v];
        if (subtree[v] > maxSize) {
            maxSize = subtree[v];
            heavy[u] = v;
        }
    }
}

void flatten(TreeNode* root) {
    if (root == nullptr)
        return;
    TreeNode* curr = root;
    while (curr != nullptr) {
        if (curr->left != nullptr) {
            TreeNode* pred =
                curr->left;
            while (pred->right != nullptr)
                pred = pred->right;
            pred->right =
                curr->right;
            curr->right =
                curr->left;
            curr->left = nullptr;
        }
        curr = curr->right;
    }
}

TreeNode* deleteNode(TreeNode* root, int key) {
    if (root == nullptr)
        return nullptr;
    if (key < root->val) {
        root->left =
            deleteNode(root->left, key);
    }
    else if (key > root->val) {
        root->right =
            deleteNode(root->right, key);
    }
    else {
        // 0 or 1 child
        if (root->left == nullptr)
            return root->right;
        if (root->right == nullptr)
            return root->left;
        // 2 children
        TreeNode* succ = root->right;
        while (succ->left != nullptr)
            succ = succ->left;
        root->val = succ->val;
        root->right =
            deleteNode(root->right, succ->val);
    }
    return root;
}

bool isValidBST(
