    long long high = LLONG_MAX) {
    if (root == nullptr)
        return true;
    if (root->val <= low ||
        root->val >= high)
        return false;
    return
        isValidBST(
            root->left,
            low,
            root->val)
        &&
        isValidBST(
            root->right,
            root->val,
            high);
}

int kthSmallest(
    TreeNode* root,
    int k) {
    stack<TreeNode*> st;
    while (root != nullptr ||
           !st.empty()) {
        while (root != nullptr) {
            st.push(root);
            root = root->left;
        }
        root = st.top();
        st.pop();
        k--;
        if (k == 0)
            return root->val;
        root = root->right;
    }
    return -1;
}

int kthLargest(
