    stack<TreeNode*> st;
    while (root != nullptr ||
           !st.empty()) {
        while (root != nullptr) {
            st.push(root);
            root = root->right;
        }
        root = st.top();
        st.pop();
        k--;
        if (k == 0)
            return root->val;
        root = root->left;
    }
    return -1;
}

