int kthSmallest(
    Node* root,
    int k) {
    while (root != nullptr) {
        int leftSize =
            getSize(root->left);
        if (k == leftSize + 1)
            return root->val;
        if (k <= leftSize) {
            root = root->left;
        }
        else {
            k -= leftSize + 1;
            root = root->right;
        }
    }
    return -1;
}

void rangeSearch(
    TreeNode* root,
    int low,
    int high,
    vector<int>& ans) {
    if (root == nullptr)
        return;
    if (root->val > low)
        rangeSearch(
            root->left,
            low,
            high,
            ans);
    if (root->val >= low &&
        root->val <= high) {
        ans.push_back(root->val);
    }
    if (root->val < high)
        rangeSearch(
            root->right,
            low,
            high,
            ans);
}

class BSTIterator {
    stack<TreeNode*> st;
    bool reverse;
    void push(TreeNode* root) {
        while (root != nullptr) {
            st.push(root);
            if (reverse)
                root = root->right;
            else
                root = root->left;
        }
    }
public:
    BSTIterator(
        TreeNode* root,
        bool rev) {
        reverse = rev;
        push(root);
    }
    int next() {
        TreeNode* node =
            st.top();
        st.pop();
        if (reverse)
            push(node->left);
        else
            push(node->right);
        return node->val;
    }
    bool hasNext() {
        return !st.empty();
    }
};
bool findTarget(
    TreeNode* root,
    int k) {
    BSTIterator left(root, false);
    BSTIterator right(root, true);
    int i = left.next();
    int j = right.next();
    while (i < j) {
        if (i + j == k)
            return true;
        if (i + j < k)
            i = left.next();
        else
            j = right.next();
    }
    return false;
}

TreeNode* sortedArrayToBST(
    vector<int>& nums,
    int l,
    int r) {
    if (l > r)
        return nullptr;
    int mid =
        l + (r - l) / 2;
    TreeNode* root =
        new TreeNode(nums[mid]);
    root->left =
        sortedArrayToBST(
            nums,
            l,
            mid - 1);
    root->right =
        sortedArrayToBST(
            nums,
            mid + 1,
            r);
    return root;
}

