vector<int> mergeBSTs(
    TreeNode* root1,
    TreeNode* root2) {
    vector<int> a, b;
    inorder(root1, a);
    inorder(root2, b);
    vector<int> ans;
    int i = 0;
    int j = 0;
    while (i < a.size() &&
           j < b.size()) {
        if (a[i] < b[j])
            ans.push_back(a[i++]);
        else
            ans.push_back(b[j++]);
    }
    while (i < a.size())
        ans.push_back(a[i++]);
    while (j < b.size())
        ans.push_back(b[j++]);
    return ans;
}

class Solution {
    TreeNode* first = nullptr;
    TreeNode* second = nullptr;
    TreeNode* prev = nullptr;
    void inorder(TreeNode* root) {
        if (root == nullptr)
            return;
        inorder(root->left);
        if (prev != nullptr &&
            prev->val > root->val) {
            if (first == nullptr)
                first = prev;
            second = root;
        }
        prev = root;
        inorder(root->right);
    }
public:
    void recoverTree(TreeNode* root) {
        inorder(root);
        swap(
            first->val,
            second->val);
    }
};

TreeNode* inorderSuccessor(
    TreeNode* root,
    TreeNode* p) {
    TreeNode* successor = nullptr;
    while (root != nullptr) {
        if (p->val < root->val) {
            successor = root;
            root = root->left;
        }
        else {
            root = root->right;
        }
    }
    return successor;
}

TreeNode* inorderPredecessor(
    TreeNode* root,
    TreeNode* p) {
    TreeNode* predecessor = nullptr;
    while (root != nullptr) {
        if (p->val > root->val) {
            predecessor = root;
            root = root->right;
        }
        else {
            root = root->left;
        }
    }
    return predecessor;
}

class BSTIterator {
    stack<TreeNode*> st;
    bool reverse;
    void pushAll(TreeNode* root) {
        while (root != nullptr) {
            st.push(root);
            if (reverse)
                root = root->right;
            else
                root = root->left;
        }
    }
public:
    BSTIterator(
        TreeNode* root,
        bool isReverse) {
        reverse = isReverse;
        pushAll(root);
    }
    int next() {
        TreeNode* node =
            st.top();
        st.pop();
        if (reverse)
            pushAll(node->left);
        else
            pushAll(node->right);
        return node->val;
    }
};

int sum = 0;
void convert(TreeNode* root) {
    if (root == nullptr)
        return;
    convert(root->right);
    sum += root->val;
    root->val = sum;
    convert(root->left);
}

