int countLessEqual(
    Node* root,
    int x) {
    int ans = 0;
    while (root != nullptr) {
        if (root->val <= x) {
            ans +=
                1 +
                (root->left
                    ? root->left->size
                    : 0);
            root = root->right;
        }
        else {
            root = root->left;
        }
    }
    return ans;
}
int rangeCount(
    Node* root,
    int L,
    int R) {
    return
        countLessEqual(root, R)
        -
        countLessEqual(root, L - 1);
}

void build(
    vector<int>& arr,
    vector<int>& tree,
    int node,
    int l,
    int r) {
    if (l == r) {
        tree[node] = arr[l];
        return;
    }
    int mid = l + (r - l) / 2;
    build(arr, tree, 2 * node,
          l, mid);
    build(arr, tree, 2 * node + 1,
          mid + 1, r);
    tree[node] =
        tree[2 * node] +
        tree[2 * node + 1];
}

int query(
    vector<int>& tree,
    int node,
    int l,
    int r,
    int ql,
    int qr) {
    if (qr < l || r < ql)
        return 0;
    if (ql <= l && r <= qr)
        return tree[node];
    int mid = l + (r - l) / 2;
    return
        query(tree, 2 * node,
              l, mid, ql, qr)
        +
        query(tree, 2 * node + 1,
              mid + 1, r, ql, qr);
}

void update(
    vector<int>& tree,
