    int l,
    int r,
    int idx,
    int val) {
    if (l == r) {
        tree[node] = val;
        return;
    }
    int mid = l + (r - l) / 2;
    if (idx <= mid) {
        update(tree, 2 * node,
               l, mid, idx, val);
    }
    else {
        update(tree, 2 * node + 1,
               mid + 1, r, idx, val);
    }
    tree[node] =
        tree[2 * node] +
        tree[2 * node + 1];
}

void push(
    vector<long long>& tree,
    vector<long long>& lazy,
    int node,
    int l,
    int r) {
    if (lazy[node] == 0)
        return;
    tree[node] +=
        (r - l + 1) * lazy[node];
    if (l != r) {
        lazy[2 * node] += lazy[node];
        lazy[2 * node + 1] +=
            lazy[node];
    }
    lazy[node] = 0;
}
