void apply(
    vector<long long>& tree,
    vector<long long>& lazy,
    vector<bool>& hasLazy,
    int node,
    int l,
    int r,
    long long val) {
    tree[node] =
        (r - l + 1) * val;
    lazy[node] = val;
    hasLazy[node] = true;
}
void push(
    vector<long long>& tree,
    vector<long long>& lazy,
    vector<bool>& hasLazy,
    int node,
    int l,
    int r) {
    if (!hasLazy[node] || l == r)
        return;
    int mid = l + (r - l) / 2;
    apply(tree, lazy, hasLazy,
          2 * node,
          l, mid,
          lazy[node]);
    apply(tree, lazy, hasLazy,
          2 * node + 1,
          mid + 1, r,
          lazy[node]);
    hasLazy[node] = false;
}
void update(
    vector<long long>& tree,
    vector<long long>& lazy,
    vector<bool>& hasLazy,
    int node,
    int l,
    int r,
    int ql,
    int qr,
    long long val) {
    if (qr < l || r < ql)
        return;
    if (ql <= l && r <= qr) {
        apply(tree, lazy, hasLazy,
              node, l, r, val);
        return;
    }
    push(tree, lazy, hasLazy,
         node, l, r);
    int mid = l + (r - l) / 2;
    update(tree, lazy, hasLazy,
           2 * node,
           l, mid,
           ql, qr, val);
    update(tree, lazy, hasLazy,
           2 * node + 1,
           mid + 1, r,
           ql, qr, val);
    tree[node] =
        tree[2 * node] +
        tree[2 * node + 1];
}

int queryMin(
    vector<int>& tree,
    int node,
    int l,
    int r,
    int ql,
    int qr) {
    if (qr < l || r < ql)
        return INT_MAX;
    if (ql <= l && r <= qr)
        return tree[node];
    int mid = l + (r - l) / 2;
    return min(
        queryMin(tree, 2 * node,
                 l, mid, ql, qr),
        queryMin(tree, 2 * node + 1,
                 mid + 1, r, ql, qr)
    );
}

int queryMax(
