    if (ql <= l && r <= qr)
        return tree[node];
    int mid = l + (r - l) / 2;
    return max(
        queryMax(tree, 2 * node,
                 l, mid, ql, qr),
        queryMax(tree, 2 * node + 1,
                 mid + 1, r, ql, qr)
    );
}

struct Node {
