    long long suff;
    long long best;
};
Node mergeNode(
    Node left,
    Node right) {
    Node res;
    res.sum =
        left.sum + right.sum;
    res.pref =
        max(
            left.pref,
            left.sum + right.pref
        );
    res.suff =
        max(
            right.suff,
            right.sum + left.suff
        );
    res.best =
        max({
            left.best,
            right.best,
            left.suff + right.pref
        });
    return res;
}
