int queryGCD(
    vector<int>& tree,
    int node,
    int l,
    int r,
    int ql,
    int qr) {
    if (qr < l || r < ql)
        return 0;
    if (ql <= l && r <= qr)
        return tree[node];
    int mid = l + (r - l) / 2;
    return gcd(
        queryGCD(tree, 2 * node,
                 l, mid, ql, qr),
        queryGCD(tree, 2 * node + 1,
                 mid + 1, r, ql, qr)
    );
}

int firstAtLeast(
    vector<int>& tree,
    int node,
    int l,
    int r,
    int ql,
    int x) {
    if (r < ql ||
        tree[node] < x)
        return -1;
    if (l == r)
        return l;
    int mid = l + (r - l) / 2;
    int left =
        firstAtLeast(
            tree,
            2 * node,
            l, mid,
            ql, x);
    if (left != -1)
        return left;
    return firstAtLeast(
        tree,
        2 * node + 1,
        mid + 1, r,
        ql, x);
}

int kthOne(
    vector<int>& tree,
    int node,
    int l,
    int r,
    int k) {
    if (l == r)
        return l;
    int mid =
        l + (r - l) / 2;
    if (tree[2 * node] >= k) {
        return kthOne(
            tree,
            2 * node,
            l, mid,
            k);
    }
    return kthOne(
        tree,
        2 * node + 1,
        mid + 1, r,
        k - tree[2 * node]);
}

vector<vector<int>> tree;
void build(
    vector<int>& arr,
    int node,
    int l,
    int r) {
    if (l == r) {
        tree[node] = {arr[l]};
        return;
    }
    int mid =
        l + (r - l) / 2;
    build(arr,
          2 * node,
          l, mid);
    build(arr,
          2 * node + 1,
          mid + 1, r);
    merge(
        tree[2 * node].begin(),
        tree[2 * node].end(),
        tree[2 * node + 1].begin(),
        tree[2 * node + 1].end(),
        back_inserter(tree[node])
    );
}
int query(
    int node,
