    int r,
    int ql,
    int qr,
    int x) {
    if (qr < l || r < ql)
        return 0;
    if (ql <= l && r <= qr) {
        return tree[node].end()
             - upper_bound(
                 tree[node].begin(),
                 tree[node].end(),
                 x);
    }
    int mid =
        l + (r - l) / 2;
    return
        query(
            2 * node,
            l, mid,
            ql, qr, x)
        +
        query(
            2 * node + 1,
            mid + 1, r,
            ql, qr, x);
}

