vector<Node> seg;
int update(
    int old,
    int l,
    int r,
    int idx) {
    int cur = seg.size();
    seg.push_back(seg[old]);
    if (l == r) {
        seg[cur].sum++;
        return cur;
    }
    int mid =
        l + (r - l) / 2;
    if (idx <= mid) {
        seg[cur].left =
            update(
                seg[old].left,
                l, mid,
                idx);
    }
    else {
        seg[cur].right =
            update(
                seg[old].right,
                mid + 1, r,
                idx);
    }
    seg[cur].sum =
        seg[seg[cur].left].sum +
        seg[seg[cur].right].sum;
    return cur;
}

