    long long val) {
    if (root == nullptr)
        root = new Node();
    if (l == r) {
        root->sum += val;
        return;
    }
    long long mid =
        l + (r - l) / 2;
    if (idx <= mid) {
        update(
            root->left,
            l, mid,
            idx, val);
    }
    else {
        update(
            root->right,
            mid + 1, r,
            idx, val);
    }
    root->sum =
        (root->left
            ? root->left->sum
            : 0)
        +
        (root->right
            ? root->right->sum
            : 0);
}

