bool remove(
    TrieNode* root,
    string word,
    int depth = 0) {
    if (root == nullptr)
        return false;
    if (depth == word.size()) {
        if (!root->isEnd)
            return false;
        root->isEnd = false;
        return true;
    }
    int x =
        word[depth] - 'a';
    if (root->child[x] == nullptr)
        return false;
    bool removed =
        remove(
            root->child[x],
            word,
            depth + 1);
    if (!removed)
        return false;
    TrieNode* child =
        root->child[x];
    bool empty = !child->isEnd;
    for (int i = 0; i < 26; i++) {
        if (child->child[i] != nullptr) {
            empty = false;
            break;
        }
    }
    if (empty) {
        delete child;
        root->child[x] = nullptr;
    }
    return true;
}

void dfs(
    TrieNode* node,
    string& current,
    vector<string>& ans) {
    if (node == nullptr)
        return;
    if (node->isEnd)
        ans.push_back(current);
    for (int i = 0; i < 26; i++) {
        if (node->child[i] != nullptr) {
            current.push_back(
                'a' + i);
            dfs(
                node->child[i],
                current,
                ans);
            current.pop_back();
        }
    }
}
vector<string> autocomplete(
    TrieNode* root,
    string prefix) {
    TrieNode* node = root;
    for (char c : prefix) {
        int x = c - 'a';
        if (node->child[x] == nullptr)
            return {};
        node = node->child[x];
    }
    vector<string> ans;
    string current = prefix;
    dfs(node, current, ans);
    return ans;
}

class Solution {
    struct Node {
        Node* child[26];
        string word;
        Node() {
            word = "";
            for (int i = 0; i < 26; i++)
                child[i] = nullptr;
        }
    };
    Node* root;
    vector<string> ans;
    void dfs(
        vector<vector<char>>& board,
        int i,
        int j,
        Node* node) {
        if (i < 0 ||
            j < 0 ||
            i >= board.size() ||
            j >= board[0].size())
            return;
        char c = board[i][j];
        if (c == '#' ||
            node->child[c - 'a'] == nullptr)
            return;
        node =
            node->child[c - 'a'];
        if (!node->word.empty()) {
            ans.push_back(node->word);
            node->word.clear();
        }
        board[i][j] = '#';
        dfs(board, i + 1, j, node);
        dfs(board, i - 1, j, node);
        dfs(board, i, j + 1, node);
        dfs(board, i, j - 1, node);
        board[i][j] = c;
    }
public:
    vector<string> findWords(
        vector<vector<char>>& board,
        vector<string>& words) {
        root = new Node();
        for (string& word : words) {
            Node* node = root;
            for (char c : word) {
                int x = c - 'a';
                if (node->child[x] == nullptr)
                    node->child[x] =
                        new Node();
                node =
                    node->child[x];
            }
            node->word = word;
        }
        for (int i = 0;
             i < board.size();
             i++) {
            for (int j = 0;
                 j < board[0].size();
                 j++) {
                dfs(
                    board,
                    i, j,
                    root);
            }
        }
        return ans;
    }
};

