void insert(
    Node* root,
    int num) {
    Node* node = root;
    for (int i = 31; i >= 0; i--) {
        int bit =
            (num >> i) & 1;
        if (node->child[bit] == nullptr)
            node->child[bit] =
                new Node();
        node =
            node->child[bit];
    }
}
int maxXOR(
    Node* root,
    int num) {
    Node* node = root;
    int ans = 0;
    for (int i = 31; i >= 0; i--) {
        int bit =
            (num >> i) & 1;
        int opposite =
            bit ^ 1;
        if (node->child[opposite]) {
            ans |= (1 << i);
            node =
                node->child[opposite];
        }
        else {
            node =
                node->child[bit];
        }
    }
    return ans;
}

