int getMaxXOR(
    Node* root,
    int num) {
    Node* node = root;
    int ans = 0;
    for (int i = 31; i >= 0; i--) {
        int bit =
            (num >> i) & 1;
        if (node->child[bit ^ 1]) {
            ans |= (1 << i);
            node =
                node->child[bit ^ 1];
        }
        else {
            node =
                node->child[bit];
        }
    }
    return ans;
}
int maxXorSubarray(
    vector<int>& arr) {
    Node* root = new Node();
    insert(root, 0);
    int prefix = 0;
    int ans = 0;
    for (int x : arr) {
        prefix ^= x;
        ans =
            max(
                ans,
                getMaxXOR(
                    root,
                    prefix));
        insert(root, prefix);
    }
    return ans;
}

struct Node {
    int child[26];
    int fail;
    vector<int> output;
    Node() {
        fail = 0;
        for (int i = 0; i < 26; i++)
            child[i] = -1;
    }
};
vector<Node> trie(1);
void insert(
    string& s,
    int id) {
    int node = 0;
    for (char c : s) {
        int x = c - 'a';
        if (trie[node].child[x] == -1) {
            trie[node].child[x] =
                trie.size();
            trie.push_back(Node());
        }
        node =
            trie[node].child[x];
    }
    trie[node].output.push_back(id);
}
void build() {
    queue<int> q;
    for (int c = 0; c < 26; c++) {
        int v = trie[0].child[c];
        if (v != -1) {
            trie[v].fail = 0;
            q.push(v);
        }
        else {
            trie[0].child[c] = 0;
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int c = 0; c < 26; c++) {
            int v =
                trie[u].child[c];
            if (v == -1) {
                trie[u].child[c] =
                    trie[
                        trie[u].fail
                    ].child[c];
                continue;
            }
            trie[v].fail =
                trie[
                    trie[u].fail
                ].child[c];
            for (int id :
                 trie[
                    trie[v].fail
                 ].output) {
                trie[v].output.push_back(id);
            }
            q.push(v);
        }
    }
}
