Text Search: O(text length + number of matches) approximately
Space: O(total pattern length × alphabet)

bool search(
    TrieNode* node,
    string& word,
    int i) {
    if (i == word.size())
        return node->isEnd;
    char c = word[i];
    if (c != '.') {
        int x = c - 'a';
        if (node->child[x] == nullptr)
            return false;
        return search(
            node->child[x],
            word,
            i + 1);
    }
    for (int x = 0; x < 26; x++) {
        if (node->child[x] &&
            search(
                node->child[x],
                word,
                i + 1)) {
            return true;
        }
    }
    return false;
}

struct Node {
    Node* child[26];
    int words;
    Node() {
        words = 0;
        for (int i = 0; i < 26; i++)
            child[i] = nullptr;
    }
};
string kthWord(
    Node* root,
    int k) {
    string ans;
    Node* node = root;
    while (node != nullptr) {
        if (node->words >= k &&
            node->words > 0) {
            // Current node itself
            // can represent a word.
            if (node->words == k)
                return ans;
        }
        for (int c = 0; c < 26; c++) {
            if (node->child[c] == nullptr)
                continue;
            int cnt =
                node->child[c]->words;
            if (k > cnt) {
                k -= cnt;
            }
            else {
                ans.push_back(
                    'a' + c);
                node =
                    node->child[c];
                break;
            }
        }
    }
    return ans;
}

struct Node {
