            child[1] = 0;
        cnt = 0;
    }
};
vector<Node> trie(1);
int insert(
    int old,
    int bitPos,
    int num) {
    int cur = trie.size();
    trie.push_back(trie[old]);
    trie[cur].cnt++;
    if (bitPos < 0)
        return cur;
    int bit =
        (num >> bitPos) & 1;
    trie[cur].child[bit] =
        insert(
            trie[old].child[bit],
            bitPos - 1,
            num);
    return cur;
}

