vector<long long> buildFenwick(vector<long long>& arr) {
    int n = arr.size() - 1;
    vector<long long> bit = arr;
    for (int i = 1; i <= n; i++) {
        int parent = i + (i & -i);
        if (parent <= n)
            bit[parent] += bit[i];
    }
    return bit;
}

int kthSmallest(vector<long long>& bit, int n, long long k) {
    int idx = 0;
    int pw = 1;
    while ((pw << 1) <= n)
        pw <<= 1;
    for (int step = pw; step > 0; step >>= 1) {
        int next = idx + step;
        if (next <= n && bit[next] < k) {
            idx = next;
            k -= bit[next];
        }
    }
    return idx + 1;
}

