class Fenwick {
    int n;
    vector<long long> bit1, bit2;
    void update(vector<long long>& bit, int idx, long long val) {
        while (idx <= n) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    }
    long long query(vector<long long>& bit, int idx) {
        long long sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    }
public:
    Fenwick(int n) : n(n), bit1(n + 1), bit2(n + 1) {}
    void rangeUpdate(int l, int r, long long val) {
        update(bit1, l, val);
        update(bit1, r + 1, -val);
        update(bit2, l, val * (l - 1));
        update(bit2, r + 1, -val * r);
    }
    long long prefixSum(int x) {
        long long s1 = query(bit1, x);
        long long s2 = query(bit2, x);
        return s1 * x - s2;
    }
    long long rangeQuery(int l, int r) {
        return prefixSum(r) - prefixSum(l - 1);
    }
};

class Fenwick2D {
    int n, m;
    vector<vector<long long>> bit;
public:
    Fenwick2D(int n, int m) : n(n), m(m),
        bit(n + 1, vector<long long>(m + 1, 0)) {}
    void update(int x, int y, long long val) {
        for (int i = x; i <= n; i += i & -i) {
            for (int j = y; j <= m; j += j & -j) {
                bit[i][j] += val;
            }
        }
    }
    long long query(int x, int y) {
        long long sum = 0;
        for (int i = x; i > 0; i -= i & -i) {
            for (int j = y; j > 0; j -= j & -j) {
                sum += bit[i][j];
            }
        }
        return sum;
    }
    long long rectangleSum(int x1, int y1, int x2, int y2) {
        return query(x2, y2)
             - query(x1 - 1, y2)
             - query(x2, y1 - 1)
             + query(x1 - 1, y1 - 1);
    }
};

