long long countIncreasing(vector<int>& arr, int K) {
    int n = arr.size();
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int M = vals.size();
    vector<vector<long long>> bit(
        K + 1,
        vector<long long>(M + 1, 0)
    );
    auto update = [&](int len, int idx, long long val) {
        while (idx <= M) {
            bit[len][idx] += val;
            idx += idx & -idx;
        }
    };
    auto query = [&](int len, int idx) {
        long long sum = 0;
        while (idx > 0) {
            sum += bit[len][idx];
            idx -= idx & -idx;
        }
        return sum;
    };
    for (int x : arr) {
        int rank = lower_bound(vals.begin(), vals.end(), x)
                   - vals.begin() + 1;
        for (int len = K; len >= 2; len--) {
            long long ways = query(len - 1, rank - 1);
            update(len, rank, ways);
        }
        update(1, rank, 1);
    }
    return query(K, M);
}

vector<long long> prefixInversions(vector<int>& arr) {
    int n = arr.size();
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = vals.size();
    vector<int> bit(m + 1, 0);
    auto update = [&](int idx) {
        while (idx <= m) {
            bit[idx]++;
            idx += idx & -idx;
        }
    };
    auto query = [&](int idx) {
        int sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    };
    vector<long long> ans;
    long long inv = 0;
    for (int i = 0; i < n; i++) {
        int rank = lower_bound(vals.begin(), vals.end(), arr[i])
                   - vals.begin() + 1;
        int smallerOrEqual = query(rank);
        inv += i - smallerOrEqual;
        ans.push_back(inv);
        update(rank);
    }
    return ans;
}

class DSU {
    vector<int> parent, sz;
public:
    DSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return;
        if (sz[a] < sz[b])
            swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
    bool same(int a, int b) {
        return find(a) == find(b);
    }
};

bool hasCycle(
