struct Edge {
    int u, v, wt;
};
int kruskal(int n, vector<Edge>& edges) {
    sort(
        edges.begin(),
        edges.end(),
        [](const Edge& a, const Edge& b) {
            return a.wt < b.wt;
        }
    );
    DSU dsu(n);
    int cost = 0;
    int used = 0;
    for (auto& e : edges) {
        if (dsu.find(e.u) == dsu.find(e.v))
            continue;
        dsu.unite(e.u, e.v);
        cost += e.wt;
        used++;
        if (used == n - 1)
            break;
    }
    return cost;
}

vector<vector<string>> accountsMerge(
    vector<vector<string>>& accounts
) {
    int n = accounts.size();
    DSU dsu(n);
    unordered_map<string, int> owner;
    for (int i = 0; i < n; i++) {
        for (int j = 1; j < accounts[i].size(); j++) {
            string email = accounts[i][j];
            if (owner.count(email))
                dsu.unite(i, owner[email]);
            else
                owner[email] = i;
        }
    }
    unordered_map<int, vector<string>> groups;
    for (auto& [email, id] : owner) {
        groups[dsu.find(id)].push_back(email);
    }
    vector<vector<string>> ans;
    for (auto& [root, emails] : groups) {
        sort(emails.begin(), emails.end());
        vector<string> cur;
        cur.push_back(accounts[root][0]);
        for (auto& email : emails)
            cur.push_back(email);
        ans.push_back(cur);
    }
    return ans;
}

int removeStones(
    vector<vector<int>>& stones
) {
    int n = stones.size();
    DSU dsu(n);
    unordered_map<int, int> row;
    unordered_map<int, int> col;
    for (int i = 0; i < n; i++) {
        int r = stones[i][0];
        int c = stones[i][1];
        if (row.count(r))
            dsu.unite(i, row[r]);
        else
            row[r] = i;
        if (col.count(c))
            dsu.unite(i, col[c]);
        else
            col[c] = i;
    }
    unordered_set<int> components;
    for (int i = 0; i < n; i++)
        components.insert(dsu.find(i));
    return n - components.size();
}

vector<int> numIslands2(
    int n,
    int m,
    vector<vector<int>>& positions
) {
    DSU dsu(n * m);
    vector<int> land(n * m, 0);
    vector<int> ans;
    int islands = 0;
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    for (auto& p : positions) {
        int x = p[0];
        int y = p[1];
        int id = x * m + y;
        if (land[id]) {
            ans.push_back(islands);
            continue;
        }
        land[id] = 1;
        islands++;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= n ||
                ny < 0 || ny >= m)
                continue;
            int nid = nx * m + ny;
            if (!land[nid])
                continue;
            if (dsu.find(id) != dsu.find(nid)) {
                dsu.unite(id, nid);
                islands--;
            }
        }
        ans.push_back(islands);
    }
    return ans;
}

class WeightedDSU {
    vector<int> parent;
    vector<long long> weight;
public:
    WeightedDSU(int n) {
        parent.resize(n);
        weight.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x)
            return x;
        int p = parent[x];
        parent[x] = find(parent[x]);
        weight[x] += weight[p];
        return parent[x];
    }
    void unite(int a, int b, long long diff) {
        // value[b] - value[a] = diff
        int ra = find(a);
        int rb = find(b);
        if (ra == rb)
            return;
        parent[rb] = ra;
        weight[rb] =
            weight[a] + diff - weight[b];
    }
    long long difference(int a, int b) {
        if (find(a) != find(b))
            return LLONG_MAX;
        // value[b] - value[a]
        return weight[b] - weight[a];
    }
};

class RollbackDSU {
    vector<int> parent, sz;
    struct Change {
        int b;
        int sizeA;
    };
    vector<Change> history;
public:
    RollbackDSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (x != parent[x])
            x = parent[x];
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            history.push_back({-1, -1});
            return;
        }
        if (sz[a] < sz[b])
            swap(a, b);
        history.push_back({b, sz[a]});
        parent[b] = a;
        sz[a] += sz[b];
    }
    int snapshot() {
        return history.size();
    }
    void rollback(int snap) {
        while (history.size() > snap) {
            auto [b, sizeA] = history.back();
            history.pop_back();
            if (b == -1)
                continue;
            int a = parent[b];
            parent[b] = b;
            sz[a] = sizeA;
        }
    }
};

struct Edge {
    int u, v;
};
void solve(
    int node,
    int l,
    int r,
    vector<vector<Edge>>& seg,
    RollbackDSU& dsu,
    vector<vector<int>>& queries,
    vector<int>& ans
) {
    int snap = dsu.snapshot();
    for (auto& e : seg[node])
        dsu.unite(e.u, e.v);
    if (l == r) {
        // Answer queries occurring at time l.
        // Example:
        // ans[l] = dsu.find(u) == dsu.find(v);
    } else {
        int mid = (l + r) / 2;
        solve(
            2 * node,
            l,
            mid,
            seg,
            dsu,
            queries,
            ans
        );
        solve(
            2 * node + 1,
            mid + 1,
            r,
            seg,
            dsu,
            queries,
            ans
        );
    }
    dsu.rollback(snap);
}

bool possibleBipartition(
    int n,
    vector<vector<int>>& dislikes
) {
    DSU dsu(2 * n);
    for (auto& e : dislikes) {
        int u = e[0] - 1;
        int v = e[1] - 1;
        int uEnemy = u + n;
        int vEnemy = v + n;
        if (dsu.find(u) == dsu.find(v))
            return false;
        dsu.unite(u, vEnemy);
        dsu.unite(v, uEnemy);
    }
    return true;
}

