vector<long long> shortestPathDAG(
    int V,
    vector<vector<pair<int,int>>>& adj,
    int src
) {
    vector<int> vis(V, 0), order;
    for (int i = 0; i < V; i++)
        if (!vis[i])
            dfs(i, adj, vis, order);
    reverse(order.begin(), order.end());
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    dist[src] = 0;
    for (int u : order) {
        if (dist[u] == INF)
            continue;
        for (auto [v, w] : adj[u])
            dist[v] = min(dist[v], dist[u] + w);
    }
    return dist;
}

vector<long long> dijkstra(
    int V,
    vector<vector<pair<int,int>>>& adj,
    int src
) {
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u])
            continue;
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

vector<long long> dijkstra(
    int V,
    vector<vector<pair<int,int>>>& adj,
    int src
) {
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    set<pair<long long,int>> st;
    dist[src] = 0;
    st.insert({0, src});
    while (!st.empty()) {
        auto [d, u] = *st.begin();
        st.erase(st.begin());
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                if (dist[v] != INF)
                    st.erase({dist[v], v});
                dist[v] = d + w;
                st.insert({dist[v], v});
            }
        }
    }
    return dist;
}

struct Edge {
    int u, v;
    long long w;
};
pair<vector<long long>, bool> bellmanFord(
    int V,
    vector<Edge>& edges,
    int src
) {
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    dist[src] = 0;
    for (int i = 1; i <= V - 1; i++) {
        bool changed = false;
        for (auto e : edges) {
            if (dist[e.u] == INF)
                continue;
            if (dist[e.u] + e.w < dist[e.v]) {
                dist[e.v] = dist[e.u] + e.w;
                changed = true;
            }
        }
        if (!changed)
            break;
    }
    for (auto e : edges) {
        if (dist[e.u] != INF &&
            dist[e.u] + e.w < dist[e.v]) {
            return {dist, true};
        }
    }
    return {dist, false};
}

void floydWarshall(vector<vector<long long>>& dist) {
    int V = dist.size();
    const long long INF = 1e18;
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            if (dist[i][k] == INF)
                continue;
            for (int j = 0; j < V; j++) {
                if (dist[k][j] == INF)
                    continue;
                dist[i][j] = min(
                    dist[i][j],
                    dist[i][k] + dist[k][j]
                );
            }
        }
    }
}

bool hasNegativeCycle(vector<vector<long long>>& dist) {
    int V = dist.size();
    for (int k = 0; k < V; k++)
        for (int i = 0; i < V; i++)
            for (int j = 0; j < V; j++)
                dist[i][j] = min(
                    dist[i][j],
                    dist[i][k] + dist[k][j]
                );
    for (int i = 0; i < V; i++) {
        if (dist[i][i] < 0)
            return true;
    }
    return false;
}

vector<long long> longestPathDAG(
