    int src
) {
    vector<int> indegree(V, 0);
    for (int u = 0; u < V; u++)
        for (auto [v, w] : adj[u])
            indegree[v]++;
    queue<int> q;
    for (int i = 0; i < V; i++)
        if (indegree[i] == 0)
            q.push(i);
    vector<int> topo;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        topo.push_back(u);
        for (auto [v, w] : adj[u])
            if (--indegree[v] == 0)
                q.push(v);
    }
    const long long NEG = -1e18;
    vector<long long> dist(V, NEG);
    dist[src] = 0;
    for (int u : topo) {
        if (dist[u] == NEG)
            continue;
        for (auto [v, w] : adj[u])
            dist[v] = max(dist[v], dist[u] + w);
    }
