long long prim(
    int V,
    vector<vector<pair<int,int>>>& adj
) {
    const long long INF = 1e18;
    vector<long long> key(V, INF);
    vector<bool> used(V, false);
    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;
    key[0] = 0;
    pq.push({0, 0});
    long long ans = 0;
    while (!pq.empty()) {
        auto [w, u] = pq.top();
        pq.pop();
        if (used[u])
            continue;
        used[u] = true;
        ans += w;
        for (auto [v, wt] : adj[u]) {
            if (!used[v] && wt < key[v]) {
                key[v] = wt;
                pq.push({wt, v});
            }
        }
    }
    return ans;
}

struct Edge {
    int u, v, w;
};
long long kruskal(int V, vector<Edge>& edges) {
    sort(edges.begin(), edges.end(),
         [](const Edge& a, const Edge& b) {
             return a.w < b.w;
         });
    DSU dsu(V);
    long long ans = 0;
    int edgesUsed = 0;
    for (auto e : edges) {
        if (dsu.unite(e.u, e.v)) {
            ans += e.w;
            edgesUsed++;
            if (edgesUsed == V - 1)
                break;
        }
    }
    return ans;
}

class DSU {
    vector<int> parent, sz;
public:
    DSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (sz[a] < sz[b])
            swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
        return true;
    }
    bool connected(int a, int b) {
        return find(a) == find(b);
    }
};

