class TarjanSCC {
    int timer = 0;
    vector<int> disc, low, inStack;
    stack<int> st;
    vector<vector<int>> scc;
    void dfs(int u, vector<vector<int>>& adj) {
        disc[u] = low[u] = timer++;
        st.push(u);
        inStack[u] = 1;
        for (int v : adj[u]) {
            if (disc[v] == -1) {
                dfs(v, adj);
                low[u] = min(low[u], low[v]);
            }
            else if (inStack[v]) {
                low[u] = min(low[u], disc[v]);
            }
        }
        if (low[u] == disc[u]) {
            vector<int> comp;
            while (true) {
                int v = st.top();
                st.pop();
                inStack[v] = 0;
                comp.push_back(v);
                if (v == u)
                    break;
            }
            scc.push_back(comp);
        }
    }
public:
    vector<vector<int>> getSCC(
        int V,
        vector<vector<int>>& adj
    ) {
        disc.assign(V, -1);
        low.resize(V);
        inStack.assign(V, 0);
        for (int i = 0; i < V; i++)
            if (disc[i] == -1)
                dfs(i, adj);
        return scc;
    }
};

void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj,
    vector<int>& disc,
    vector<int>& low,
    int& timer,
    vector<pair<int,int>>& bridges
) {
    disc[u] = low[u] = timer++;
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        if (disc[v] == -1) {
            dfs(v, u, adj, disc, low, timer, bridges);
            low[u] = min(low[u], low[v]);
            if (low[v] > disc[u])
                bridges.push_back({u, v});
        }
        else {
            low[u] = min(low[u], disc[v]);
        }
    }
}
vector<pair<int,int>> findBridges(
    int V,
    vector<vector<int>>& adj
) {
    vector<int> disc(V, -1), low(V);
    vector<pair<int,int>> bridges;
    int timer = 0;
    for (int i = 0; i < V; i++) {
        if (disc[i] == -1)
            dfs(i, -1, adj, disc, low, timer, bridges);
    }
    return bridges;
}

void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj,
    vector<int>& disc,
    vector<int>& low,
    vector<int>& isArt,
    int& timer
) {
    disc[u] = low[u] = timer++;
    int children = 0;
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        if (disc[v] == -1) {
            children++;
            dfs(v, u, adj, disc, low, isArt, timer);
            low[u] = min(low[u], low[v]);
            if (parent != -1 &&
                low[v] >= disc[u])
                isArt[u] = 1;
        }
        else {
            low[u] = min(low[u], disc[v]);
        }
    }
    if (parent == -1 && children > 1)
        isArt[u] = 1;
}
