void dfs(int u,
         vector<vector<pair<int,int>>>& adj,
         vector<bool>& used,
         vector<int>& path) {
    while (!adj[u].empty()) {
        auto [v, id] = adj[u].back();
        adj[u].pop_back();
        if (used[id])
            continue;
        used[id] = true;
        dfs(v, adj, used, path);
    }
    path.push_back(u);
}
vector<int> eulerPath(
    int V,
    vector<vector<pair<int,int>>> adj,
    int start
) {
    int E = 0;
    for (auto& x : adj)
        E += x.size();
    E /= 2;
    vector<bool> used(E, false);
    vector<int> path;
    dfs(start, adj, used, path);
    reverse(path.begin(), path.end());
    if ((int)path.size() != E + 1)
        return {};
    return path;
}

bool hasEulerianPath(
