) {
    int odd = 0;
    for (int i = 0; i < V; i++) {
        if (adj[i].size() % 2)
            odd++;
    }
    return odd == 0 || odd == 2;
}

bool hamiltonianPath(
    int V,
    vector<vector<int>>& adj
) {
    int N = 1 << V;
    vector<vector<char>> dp(N, vector<char>(V, false));
    for (int i = 0; i < V; i++)
        dp[1 << i][i] = true;
    for (int mask = 0; mask < N; mask++) {
        for (int u = 0; u < V; u++) {
            if (!dp[mask][u])
                continue;
            for (int v : adj[u]) {
                if (!(mask & (1 << v))) {
                    dp[mask | (1 << v)][v] = true;
                }
            }
        }
    }
    for (int i = 0; i < V; i++)
        if (dp[N - 1][i])
            return true;
    return false;
}

