class HopcroftKarp {
    int n, m;
    vector<vector<int>> adj;
    vector<int> pairU, pairV, dist;
    bool bfs() {
        queue<int> q;
        for (int u = 0; u < n; u++) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                q.push(u);
            }
            else {
                dist[u] = -1;
            }
        }
        bool found = false;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                int nxt = pairV[v];
                if (nxt == -1) {
                    found = true;
                }
                else if (dist[nxt] == -1) {
                    dist[nxt] = dist[u] + 1;
                    q.push(nxt);
                }
            }
        }
        return found;
    }
    bool dfs(int u) {
        for (int v : adj[u]) {
            int nxt = pairV[v];
            if (nxt == -1 ||
                (dist[nxt] == dist[u] + 1 &&
                 dfs(nxt))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }
public:
    HopcroftKarp(int n, int m,
                 vector<vector<int>>& graph)
        : n(n), m(m), adj(graph) {
        pairU.assign(n, -1);
        pairV.assign(m, -1);
        dist.resize(n);
    }
    int maximumMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 0; u < n; u++) {
                if (pairU[u] == -1 && dfs(u))
                    matching++;
            }
        }
        return matching;
    }
};

int maxFlow(
    int V,
    vector<vector<int>> capacity,
    int s,
    int t
) {
    int flow = 0;
    while (true) {
        vector<int> parent(V, -1);
        queue<int> q;
        q.push(s);
        parent[s] = s;
        while (!q.empty() && parent[t] == -1) {
            int u = q.front();
            q.pop();
            for (int v = 0; v < V; v++) {
                if (parent[v] == -1 &&
                    capacity[u][v] > 0) {
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        if (parent[t] == -1)
            break;
        int pushed = INT_MAX;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            pushed = min(pushed, capacity[u][v]);
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            capacity[u][v] -= pushed;
            capacity[v][u] += pushed;
        }
        flow += pushed;
    }
    return flow;
}

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    int n;
    vector<vector<Edge>> adj;
    vector<int> level, ptr;
    Dinic(int n) : n(n) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }
    void addEdge(int u, int v, int cap) {
        Edge a{v, (int)adj[v].size(), cap};
        Edge b{u, (int)adj[u].size(), 0};
        adj[u].push_back(a);
        adj[v].push_back(b);
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (auto& e : adj[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }
    int dfs(int u, int t, int pushed) {
        if (pushed == 0)
            return 0;
        if (u == t)
            return pushed;
        for (int& cid = ptr[u];
             cid < (int)adj[u].size();
             cid++) {
            Edge& e = adj[u][cid];
            if (e.cap <= 0 ||
                level[e.to] != level[u] + 1)
                continue;
            int tr = dfs(
                e.to,
                t,
                min(pushed, e.cap)
            );
            if (tr == 0)
                continue;
            e.cap -= tr;
            adj[e.to][e.rev].cap += tr;
            return tr;
        }
        return 0;
    }
    int maxFlow(int s, int t) {
        int flow = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int pushed = dfs(s, t, INT_MAX))
                flow += pushed;
        }
        return flow;
    }
};

vector<int> solve2SAT(
    int n,
    vector<pair<int,int>>& clauses
) {
    int N = 2 * n;
    vector<vector<int>> adj(N);
    auto node = [&](int x) {
        int v = abs(x) - 1;
        return x > 0 ? 2 * v : 2 * v + 1;
    };
    auto neg = [&](int x) {
        return x ^ 1;
    };
    for (auto [a, b] : clauses) {
        int A = node(a);
        int B = node(b);
        adj[neg(A)].push_back(B);
        adj[neg(B)].push_back(A);
    }
    // Kosaraju
    vector<int> vis(N), order;
    function<void(int)> dfs1 = [&](int u) {
        vis[u] = 1;
        for (int v : adj[u])
            if (!vis[v])
                dfs1(v);
        order.push_back(u);
    };
    for (int i = 0; i < N; i++)
        if (!vis[i])
            dfs1(i);
    vector<vector<int>> rev(N);
    for (int u = 0; u < N; u++)
        for (int v : adj[u])
            rev[v].push_back(u);
    vector<int> comp(N, -1);
    function<void(int,int)> dfs2 =
        [&](int u, int c) {
            comp[u] = c;
            for (int v : rev[u])
                if (comp[v] == -1)
                    dfs2(v, c);
        };
    reverse(order.begin(), order.end());
    int c = 0;
    for (int u : order)
        if (comp[u] == -1)
            dfs2(u, c++);
    for (int i = 0; i < n; i++) {
        if (comp[2 * i] == comp[2 * i + 1])
            return {};
    }
    vector<int> assignment(n);
    for (int i = 0; i < n; i++)
        assignment[i] = comp[2 * i] > comp[2 * i + 1];
    return assignment;
}

const int LOG = 20;
vector<vector<int>> up;
vector<int> depth;
void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj
) {
    up[u][0] = parent;
    for (int j = 1; j < LOG; j++)
        up[u][j] =
            up[up[u][j - 1]][j - 1];
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        depth[v] = depth[u] + 1;
        dfs(v, u, adj);
    }
}
int LCA(int u, int v) {
    if (depth[u] < depth[v])
        swap(u, v);
    int diff = depth[u] - depth[v];
    for (int j = LOG - 1; j >= 0; j--) {
        if (diff & (1 << j))
            u = up[u][j];
    }
    if (u == v)
        return u;
    for (int j = LOG - 1; j >= 0; j--) {
        if (up[u][j] != up[v][j]) {
            u = up[u][j];
            v = up[v][j];
        }
    }
    return up[u][0];
}

class RollbackDSU {
    vector<int> parent, sz;
    vector<pair<int,int>> history;
public:
    RollbackDSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (x != parent[x])
            x = parent[x];
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            history.push_back({-1, -1});
            return;
        }
        if (sz[a] < sz[b])
            swap(a, b);
        history.push_back({a, b});
        parent[b] = a;
        sz[a] += sz[b];
    }
    void rollback() {
        auto [a, b] = history.back();
        history.pop_back();
        if (a == -1)
            return;
        parent[b] = b;
        sz[a] -= sz[b];
    }
};

vector<int> shortestPath(
    int V,
    vector<vector<pair<int,int>>>& adj,
    int src,
    int dest
) {
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    vector<int> parent(V, -1);
    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u])
            continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    if (dist[dest] == INF)
        return {};
    vector<int> path;
    for (int u = dest; u != -1; u = parent[u])
        path.push_back(u);
    reverse(path.begin(), path.end());
    return path;
}

void transitiveClosure(vector<vector<int>>& reach) {
    int V = reach.size();
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                reach[i][j] =
                    reach[i][j] ||
                    (reach[i][k] && reach[k][j]);
            }
        }
    }
}

void dfs(
    int u,
    int parent,
    vector<vector<int>>& adj,
    vector<int>& tin,
    vector<int>& low,
    int& timer,
    vector<pair<int,int>>& bridges
) {
    tin[u] = low[u] = timer++;
    for (int v : adj[u]) {
        if (v == parent)
            continue;
        if (tin[v] == -1) {
            dfs(v, u, adj, tin, low,
                timer, bridges);
            low[u] = min(low[u], low[v]);
            if (low[v] > tin[u])
                bridges.push_back({u, v});
        }
        else {
            low[u] = min(low[u], tin[v]);
        }
    }
}

