}

int cheapest(
    int V,
    vector<Edge>& edges,
    int src,
    int dst,
    int K
) {
    const int INF = 1e9;
    vector<int> dist(V, INF);
    dist[src] = 0;
    for (int i = 0; i <= K; i++) {
        vector<int> ndist = dist;
        for (auto e : edges) {
            if (dist[e.u] == INF)
                continue;
            ndist[e.v] = min(
                ndist[e.v],
                dist[e.u] + e.w
            );
        }
        dist = ndist;
    }
    return dist[dst] == INF ? -1 : dist[dst];
}

int unboundedKnapsack(vector<int>& wt, vector<int>& val, int W) {
    int n = wt.size();
    vector<int> dp(W + 1, 0);
    for (int w = 0; w <= W; w++) {
        for (int i = 0; i < n; i++) {
            if (wt[i] <= w) {
                dp[w] = max(dp[w], val[i] + dp[w - wt[i]]);
            }
        }
    }
    return dp[W];
}

int coinChange(vector<int>& coins, int amount) {
    const int INF = 1e9;
    vector<int> dp(amount + 1, INF);
    dp[0] = 0;
    for (int x = 1; x <= amount; x++) {
        for (int coin : coins) {
            if (coin <= x) {
                dp[x] = min(dp[x], 1 + dp[x - coin]);
            }
        }
    }
    return dp[amount] == INF ? -1 : dp[amount];
}

long long coinChangeWays(vector<int>& coins, int amount) {
    vector<long long> dp(amount + 1, 0);
    dp[0] = 1;
    for (int coin : coins) {
        for (int x = coin; x <= amount; x++) {
            dp[x] += dp[x - coin];
        }
    }
    return dp[amount];
}

bool canPartition(vector<int>& nums) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (sum % 2) return false;
    int target = sum / 2;
    vector<bool> dp(target + 1, false);
    dp[0] = true;
    for (int x : nums) {
        for (int s = target; s >= x; s--) {
            dp[s] = dp[s] || dp[s - x];
        }
    }
    return dp[target];
}

int findTargetSumWays(vector<int>& nums, int target) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (abs(target) > sum || (sum + target) % 2)
        return 0;
    int need = (sum + target) / 2;
    vector<int> dp(need + 1, 0);
    dp[0] = 1;
    for (int x : nums) {
        for (int s = need; s >= x; s--) {
            dp[s] += dp[s - x];
        }
    }
    return dp[need];
}

int rob(vector<int>& nums) {
