    if (n == 1) return nums[0];
    return max(
        solve(nums, 0, n - 2),
        solve(nums, 1, n - 1)
    );
}

int maxProfit(int K, vector<int>& prices) {
    int n = prices.size();
    vector<vector<int>> dp(
        K + 1,
        vector<int>(2, 0)
    );
    for (int k = 1; k <= K; k++) {
        dp[k][1] = -prices[0];
    }
    for (int i = 1; i < n; i++) {
        for (int k = 1; k <= K; k++) {
            dp[k][0] = max(
                dp[k][0],
                dp[k][1] + prices[i]
            );
            dp[k][1] = max(
                dp[k][1],
                dp[k - 1][0] - prices[i]
            );
        }
    }
    return dp[K][0];
}

int maxProfit(vector<int>& prices) {
    int hold = -prices[0];
    int sold = 0;
    int cooldown = 0;
    for (int i = 1; i < prices.size(); i++) {
        int oldHold = hold;
        int oldSold = sold;
        int oldCooldown = cooldown;
        hold = max(oldHold, oldCooldown - prices[i]);
        sold = oldHold + prices[i];
        cooldown = max(oldCooldown, oldSold);
    }
    return max(sold, cooldown);
}

int maxProfit(vector<int>& prices, int fee) {
    int hold = -prices[0];
    int cash = 0;
    for (int i = 1; i < prices.size(); i++) {
        int oldHold = hold;
        hold = max(hold, cash - prices[i]);
        cash = max(cash, oldHold + prices[i] - fee);
    }
    return cash;
}

int maxCoins(vector<int>& nums) {
    int n = nums.size();
    nums.insert(nums.begin(), 1);
    nums.push_back(1);
    vector<vector<int>> dp(
        n + 2,
        vector<int>(n + 2, 0)
    );
    for (int len = 1; len <= n; len++) {
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            for (int k = l; k <= r; k++) {
                dp[l][r] = max(
                    dp[l][r],
                    nums[l - 1] * nums[k] * nums[r + 1]
                    + dp[l][k - 1]
                    + dp[k + 1][r]
                );
            }
        }
    }
    return dp[1][n];
}

long long solve(
    string& s,
    int l,
    int r,
    bool want,
    vector<vector<vector<long long>>>& dp
) {
    if (l == r)
        return (s[l] == 'T') == want;
    if (dp[l][r][want] != -1)
        return dp[l][r][want];
    long long ans = 0;
    for (int k = l + 1; k < r; k += 2) {
        long long LT = solve(s, l, k - 1, true, dp);
        long long LF = solve(s, l, k - 1, false, dp);
        long long RT = solve(s, k + 1, r, true, dp);
        long long RF = solve(s, k + 1, r, false, dp);
        if (s[k] == '&') {
            if (want)
                ans += LT * RT;
            else
                ans += LT * RF + LF * RT + LF * RF;
        }
        else if (s[k] == '|') {
            if (want)
                ans += LT * RT + LT * RF + LF * RT;
            else
                ans += LF * RF;
        }
        else {
            if (want)
                ans += LT * RF + LF * RT;
            else
                ans += LT * RT + LF * RF;
        }
    }
    return dp[l][r][want] = ans;
}

