long long solve(
    string& s,
    int pos,
    int prev,
    int tight,
    int started
) {
    if (pos == s.size())
        return 1;
    if (vis[pos][prev + 1][tight][started])
        return dp[pos][prev + 1][tight][started];
    vis[pos][prev + 1][tight][started] = true;
    int limit = tight ? s[pos] - '0' : 9;
    long long ans = 0;
    for (int d = 0; d <= limit; d++) {
        int newTight = tight && (d == limit);
        if (started && d == prev)
            continue;
        if (!started && d == 0) {
            ans += solve(
                s, pos + 1, -1,
                newTight, 0
            );
        }
        else {
            ans += solve(
                s, pos + 1, d,
                newTight, 1
            );
        }
    }
    return dp[pos][prev + 1][tight][started] = ans;
}

int solve(
    int worker,
    int mask,
    vector<vector<int>>& cost,
    vector<int>& dp
) {
    int n = cost.size();
    if (worker == n)
        return 0;
    if (dp[mask] != -1)
        return dp[mask];
    int ans = 1e9;
    for (int job = 0; job < n; job++) {
        if (!(mask & (1 << job))) {
            ans = min(
                ans,
                cost[worker][job] +
                solve(
                    worker + 1,
                    mask | (1 << job),
                    cost,
                    dp
                )
            );
        }
    }
    return dp[mask] = ans;
}

void SOSDP(vector<int>& a) {
    int n = 0;
    while ((1 << n) < a.size())
        n++;
    for (int bit = 0; bit < n; bit++) {
        for (int mask = 0; mask < (1 << n); mask++) {
            if (mask & (1 << bit)) {
                a[mask] += a[mask ^ (1 << bit)];
            }
        }
    }
}

