            dp[l][r] = 1e9;
            for (int k = l + 1; k < r; k++) {
                dp[l][r] = min(
                    dp[l][r],
                    cuts[r] - cuts[l]
                    + dp[l][k]
                    + dp[k][r]
                );
            }
        }
    }
    return dp[0][m - 1];
}

int eggDrop(int eggs, int floors) {
    vector<int> dp(eggs + 1, 0);
    int moves = 0;
    while (dp[eggs] < floors) {
        moves++;
        for (int e = eggs; e >= 1; e--) {
            dp[e] = dp[e] + dp[e - 1] + 1;
        }
    }
    return moves;
}

class Solution {
public:
    vector<vector<string>> ans;
    vector<string> board;
    vector<int> col, diag1, diag2;
    void solve(int row, int n) {
        if (row == n) {
            ans.push_back(board);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (col[c] || diag1[row - c + n - 1] || diag2[row + c])
                continue;
            board[row][c] = 'Q';
            col[c] = diag1[row - c + n - 1] = diag2[row + c] = 1;
            solve(row + 1, n);
            board[row][c] = '.';
            col[c] = diag1[row - c + n - 1] = diag2[row + c] = 0;
        }
    }
    vector<vector<string>> solveNQueens(int n) {
        board = vector<string>(n, string(n, '.'));
        col.resize(n);
        diag1.resize(2 * n - 1);
        diag2.resize(2 * n - 1);
        solve(0, n);
        return ans;
    }
};

class Solution {
public:
    bool solve(vector<vector<char>>& board,
               vector<int>& row,
               vector<int>& col,
               vector<int>& box) {
        int r = -1, c = -1;
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') {
                    r = i;
                    c = j;
                    break;
                }
            }
            if (r != -1) break;
        }
        if (r == -1) return true;
        int b = (r / 3) * 3 + c / 3;
        for (int num = 1; num <= 9; num++) {
            int bit = 1 << num;
            if ((row[r] & bit) || (col[c] & bit) || (box[b] & bit))
                continue;
            board[r][c] = char('0' + num);
            row[r] |= bit;
            col[c] |= bit;
            box[b] |= bit;
            if (solve(board, row, col, box))
                return true;
            board[r][c] = '.';
            row[r] ^= bit;
            col[c] ^= bit;
            box[b] ^= bit;
        }
        return false;
    }
    void solveSudoku(vector<vector<char>>& board) {
        vector<int> row(9), col(9), box(9);
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') continue;
                int bit = 1 << (board[i][j] - '0');
                row[i] |= bit;
                col[j] |= bit;
                box[(i / 3) * 3 + j / 3] |= bit;
            }
        }
        solve(board, row, col, box);
    }
};

class Solution {
    struct Node {
        Node* child[26] = {};
        string word = "";
    };
    Node* root = new Node();
    vector<string> ans;
    int n, m;
    void insert(string& s) {
        Node* cur = root;
        for (char c : s) {
            int x = c - 'a';
            if (!cur->child[x])
                cur->child[x] = new Node();
            cur = cur->child[x];
        }
        cur->word = s;
    }
    void dfs(vector<vector<char>>& board, int r, int c, Node* node) {
        if (r < 0 || r >= n || c < 0 || c >= m ||
            board[r][c] == '#')
            return;
        char ch = board[r][c];
        Node* next = node->child[ch - 'a'];
        if (!next) return;
        if (!next->word.empty()) {
            ans.push_back(next->word);
            next->word.clear();
        }
        board[r][c] = '#';
        dfs(board, r + 1, c, next);
        dfs(board, r - 1, c, next);
        dfs(board, r, c + 1, next);
        dfs(board, r, c - 1, next);
        board[r][c] = ch;
    }
public:
    vector<string> findWords(vector<vector<char>>& board,
                             vector<string>& words) {
        n = board.size();
        m = board[0].size();
        for (auto& word : words)
            insert(word);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                dfs(board, i, j, root);
        return ans;
    }
};

class Solution {
public:
    vector<vector<string>> ans;
    vector<string> cur;
    vector<vector<bool>> pal;
    void backtrack(string& s, int start) {
        if (start == s.size()) {
            ans.push_back(cur);
            return;
        }
        for (int end = start; end < s.size(); end++) {
            if (!pal[start][end])
                continue;
            cur.push_back(s.substr(start, end - start + 1));
            backtrack(s, end + 1);
            cur.pop_back();
        }
    }
    vector<vector<string>> partition(string s) {
        int n = s.size();
        pal.assign(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s[i] == s[j] &&
                    (j - i <= 2 || pal[i + 1][j - 1]))
                    pal[i][j] = true;
            }
        }
        backtrack(s, 0);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> ans;
    vector<int> cur;
    void solve(vector<int>& nums, int start, int target) {
        if (target == 0) {
            ans.push_back(cur);
            return;
        }
        for (int i = start; i < nums.size(); i++) {
            if (i > start && nums[i] == nums[i - 1])
                continue;
            if (nums[i] > target)
                break;
            cur.push_back(nums[i]);
            solve(nums, i + 1, target - nums[i]);
            cur.pop_back();
        }
    }
    vector<vector<int>> combinationSum2(vector<int>& nums,
                                         int target) {
        sort(nums.begin(), nums.end());
        solve(nums, 0, target);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> ans;
    vector<int> cur;
    vector<bool> used;
    void solve(vector<int>& nums) {
        if (cur.size() == nums.size()) {
            ans.push_back(cur);
            return;
        }
        for (int i = 0; i < nums.size(); i++) {
            if (used[i])
                continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1])
                continue;
            used[i] = true;
            cur.push_back(nums[i]);
            solve(nums);
            cur.pop_back();
            used[i] = false;
        }
    }
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        used.resize(nums.size());
        solve(nums);
        return ans;
    }
};

class Solution {
public:
    vector<string> ans;
    void solve(string& cur, int open, int close, int n) {
        if (cur.size() == 2 * n) {
            ans.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            solve(cur, open + 1, close, n);
            cur.pop_back();
        }
        if (close < open) {
            cur.push_back(')');
            solve(cur, open, close + 1, n);
            cur.pop_back();
        }
    }
    vector<string> generateParenthesis(int n) {
        string cur;
        solve(cur, 0, 0, n);
        return ans;
    }
};

class Solution {
public:
    unordered_set<string> dict;
    unordered_map<int, vector<string>> memo;
    vector<string> solve(string& s, int start) {
        if (start == s.size())
            return {""};
        if (memo.count(start))
            return memo[start];
        vector<string> ans;
        string word;
        for (int i = start; i < s.size(); i++) {
            word += s[i];
            if (!dict.count(word))
                continue;
            vector<string> suffix = solve(s, i + 1);
            for (string& x : suffix) {
                if (x.empty())
                    ans.push_back(word);
                else
                    ans.push_back(word + " " + x);
            }
        }
        return memo[start] = ans;
    }
    vector<string> wordBreak(string s, vector<string>& wordDict) {
        for (auto& word : wordDict)
            dict.insert(word);
        return solve(s, 0);
    }
};

class Solution {
public:
    vector<int> digit(26, -1);
    vector<bool> used(10, false);
    bool solve(vector<string>& words, string& result,
               int idx, int carry, int pos) {
        if (pos == result.size())
            return carry == 0;
        int sum = carry;
        for (string& word : words) {
            int p = word.size() - 1 - pos;
            if (p < 0) continue;
            int c = word[p] - 'A';
            if (digit[c] == -1)
                return false;
            sum += digit[c];
        }
        int resChar = result[result.size() - 1 - pos] - 'A';
        int required = sum % 10;
        int nextCarry = sum / 10;
        if (digit[resChar] != -1)
            return digit[resChar] == required &&
                   solve(words, result, idx, nextCarry, pos + 1);
        if (used[required])
            return false;
        digit[resChar] = required;
        used[required] = true;
        if (solve(words, result, idx, nextCarry, pos + 1))
            return true;
        digit[resChar] = -1;
        used[required] = false;
        return false;
    }
};

vector<int> zeroOneBFS(int n, vector<vector<pair<int,int>>>& adj, int src) {
    const int INF = 1e9;
    vector<int> dist(n, INF);
    deque<int> dq;
    dist[src] = 0;
    dq.push_front(src);
    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (w == 0)
                    dq.push_front(v);
                else
                    dq.push_back(v);
            }
        }
    }
    return dist;
}

vector<int> shortestPath(int n,
                         vector<vector<pair<int,int>>>& adj,
                         int src, int dest) {
    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    vector<int> parent(n, -1);
    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u])
            continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    if (dist[dest] == INF)
        return {};
    vector<int> path;
    for (int v = dest; v != -1; v = parent[v])
        path.push_back(v);
    reverse(path.begin(), path.end());
    return path;
}

long long shortestKEdges(int n,
                         vector<vector<pair<int,int>>>& adj,
                         int src, int dest, int K) {
    const long long INF = 1e18;
    vector<long long> prev(n, INF);
    prev[src] = 0;
    for (int edges = 1; edges <= K; edges++) {
        vector<long long> curr(n, INF);
        for (int u = 0; u < n; u++) {
            if (prev[u] == INF)
                continue;
            for (auto [v, w] : adj[u]) {
                curr[v] = min(curr[v], prev[u] + w);
            }
        }
        prev = curr;
    }
    return prev[dest];
}

vector<long long> countShortestPaths(
    int n,
    vector<vector<pair<int,int>>>& adj,
    int src) {
    const long long INF = 1e18;
    const long long MOD = 1e9 + 7;
    vector<long long> dist(n, INF);
    vector<long long> ways(n, 0);
    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;
    dist[src] = 0;
    ways[src] = 1;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u])
            continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                ways[v] = ways[u];
                pq.push({dist[v], v});
            }
            else if (d + w == dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }
    return ways;
}

void dfs(int u, vector<vector<int>>& adj,
