bool hamiltonianPath(int n, vector<vector<int>>& adj) {
    int N = 1 << n;
    vector<vector<bool>> dp(N, vector<bool>(n, false));
    for (int i = 0; i < n; i++)
        dp[1 << i][i] = true;
    for (int mask = 0; mask < N; mask++) {
        for (int u = 0; u < n; u++) {
            if (!dp[mask][u])
                continue;
            for (int v : adj[u]) {
                if (!(mask & (1 << v))) {
                    dp[mask | (1 << v)][v] = true;
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (dp[N - 1][i])
            return true;
    }
    return false;
}

