    int components) {
    dag.assign(components, {});
    set<pair<int,int>> edges;
    for (int u = 0; u < n; u++) {
        for (int v : adj[u]) {
            if (component[u] != component[v]) {
                edges.insert({component[u], component[v]});
            }
        }
    }
    for (auto [u, v] : edges)
        dag[u].push_back(v);
}

void addClause(int x, bool xVal,
               int y, bool yVal,
               vector<vector<int>>& g) {
    int a = 2 * x + xVal;
    int b = 2 * y + yVal;
    int na = 2 * x + (!xVal);
    int nb = 2 * y + (!yVal);
    g[na].push_back(b);
    g[nb].push_back(a);
}

int minEdgesToMakeStrong(
    int components,
    vector<int>& indegree,
    vector<int>& outdegree) {
    if (components == 1)
        return 0;
    int sources = 0;
    int sinks = 0;
    for (int i = 0; i < components; i++) {
        if (indegree[i] == 0)
            sources++;
        if (outdegree[i] == 0)
            sinks++;
    }
    return max(sources, sinks);
}

class DSU {
    vector<int> parent, sz;
public:
    DSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return;
        if (sz[a] < sz[b])
            swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
    bool connected(int a, int b) {
        return find(a) == find(b);
    }
};

int minimaxPath(int n,
                vector<vector<pair<int,int>>>& adj,
                int src, int dest) {
    const int INF = 1e9;
    vector<int> dist(n, INF);
    priority_queue<
        pair<int,int>,
        vector<pair<int,int>>,
        greater<pair<int,int>>
    > pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u])
            continue;
        for (auto [v, w] : adj[u]) {
            int nd = max(d, w);
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }
    return dist[dest];
}

struct Edge {
    int u, v, w;
};
int maximumSpanningTree(int n, vector<Edge>& edges) {
    sort(edges.begin(), edges.end(),
         [](const Edge& a, const Edge& b) {
             return a.w > b.w;
         });
    DSU dsu(n);
    int ans = 0;
    int count = 0;
    for (auto& e : edges) {
        if (dsu.find(e.u) != dsu.find(e.v)) {
            dsu.unite(e.u, e.v);
            ans += e.w;
            count++;
        }
    }
    return count == n - 1 ? ans : -1;
}

bool canColor(int u, int n, int m,
              vector<vector<int>>& adj,
              vector<int>& color) {
    if (u == n)
        return true;
    for (int c = 1; c <= m; c++) {
        bool ok = true;
        for (int v : adj[u]) {
            if (color[v] == c) {
                ok = false;
                break;
            }
        }
        if (!ok)
            continue;
        color[u] = c;
        if (canColor(u + 1, n, m, adj, color))
            return true;
        color[u] = 0;
    }
    return false;
}

long long shortestWithDiscount(
    int n,
    vector<vector<pair<int,int>>>& adj,
    int src,
    int dest) {
    const long long INF = 1e18;
    vector<vector<long long>> dist(n,
        vector<long long>(2, INF));
    using T = tuple<long long,int,int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    dist[src][0] = 0;
    pq.push({0, src, 0});
    while (!pq.empty()) {
        auto [d, u, used] = pq.top();
        pq.pop();
        if (d != dist[u][used])
            continue;
        for (auto [v, w] : adj[u]) {
            // Don't use discount.
            if (d + w < dist[v][used]) {
                dist[v][used] = d + w;
                pq.push({dist[v][used], v, used});
            }
            // Use discount on this edge.
            if (!used && d < dist[v][1]) {
                dist[v][1] = d;
                pq.push({d, v, 1});
            }
        }
    }
    return min(dist[dest][0], dist[dest][1]);
}

vector<int> multiSourceBFS(
    int n,
    vector<vector<int>>& adj,
    vector<int>& sources) {
    vector<int> dist(n, -1);
    queue<int> q;
    for (int src : sources) {
        dist[src] = 0;
        q.push(src);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] != -1)
                continue;
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }
    return dist;
}

int shortestPath(
    vector<vector<int>>& grid,
    int K) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<int>> best(
        n, vector<int>(m, K + 1));
    queue<tuple<int,int,int>> q;
    q.push({0, 0, 0});
    best[0][0] = 0;
    int dist = 0;
    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            auto [r, c, used] = q.front();
            q.pop();
            if (r == n - 1 && c == m - 1)
                return dist;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= n ||
                    nc < 0 || nc >= m)
                    continue;
                int nu = used + grid[nr][nc];
                if (nu <= K && nu < best[nr][nc]) {
                    best[nr][nc] = nu;
                    q.push({nr, nc, nu});
                }
            }
        }
        dist++;
    }
    return -1;
}

struct Node {
    int child[26];
    int fail;
    vector<int> output;
    Node() {
        memset(child, -1, sizeof(child));
        fail = 0;
    }
};
vector<Node> trie(1);
void insert(string s, int id) {
    int node = 0;
    for (char c : s) {
        int x = c - 'a';
        if (trie[node].child[x] == -1) {
            trie[node].child[x] = trie.size();
            trie.push_back(Node());
        }
        node = trie[node].child[x];
    }
    trie[node].output.push_back(id);
}
void build() {
    queue<int> q;
    for (int c = 0; c < 26; c++) {
        int v = trie[0].child[c];
        if (v != -1) {
            trie[v].fail = 0;
            q.push(v);
        }
        else {
            trie[0].child[c] = 0;
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int c = 0; c < 26; c++) {
            int v = trie[u].child[c];
            if (v != -1) {
                trie[v].fail = trie[trie[u].fail].child[c];
                for (int id : trie[trie[v].fail].output)
                    trie[v].output.push_back(id);
                q.push(v);
            }
            else {
                trie[u].child[c] = trie[trie[u].fail].child[c];
            }
        }
    }
}
vector<pair<int, int>> search(string text) {
    vector<pair<int, int>> ans;
    int node = 0;
    for (int i = 0; i < text.size(); i++) {
        node = trie[node].child[text[i] - 'a'];
        for (int id : trie[node].output) {
            ans.push_back({id, i});
        }
    }
    return ans;
}

vector<int> buildSuffixArray(string s) {
    int n = s.size();
    vector<int> sa(n), rnk(n);
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        rnk[i] = s[i];
    }
    for (int k = 1; k < n; k *= 2) {
        auto cmp = [&](int a, int b) {
            if (rnk[a] != rnk[b])
                return rnk[a] < rnk[b];
            int ra = (a + k < n) ? rnk[a + k] : -1;
            int rb = (b + k < n) ? rnk[b + k] : -1;
            return ra < rb;
        };
        sort(sa.begin(), sa.end(), cmp);
        vector<int> newRank(n);
        newRank[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            newRank[sa[i]] = newRank[sa[i - 1]] +
                cmp(sa[i - 1], sa[i]);
        }
        rnk = newRank;
        if (rnk[sa[n - 1]] == n - 1)
            break;
    }
    return sa;
}
Time Complexity: O(n log² n) using comparison sort.

vector<int> buildLCP(string s, vector<int>& sa) {
    int n = s.size();
    vector<int> rank(n), lcp(n);
    for (int i = 0; i < n; i++)
        rank[sa[i]] = i;
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] == n - 1) {
            k = 0;
            continue;
        }
        int j = sa[rank[i] + 1];
        while (i + k < n &&
               j + k < n &&
               s[i + k] == s[j + k]) {
            k++;
        }
        lcp[rank[i]] = k;
        if (k)
            k--;
    }
    return lcp;
}
Time Complexity: O(n) after the suffix array is built.

