struct State {
    int next[26];
    int link;
    int len;
    State() {
        memset(next, -1, sizeof(next));
        link = -1;
        len = 0;
    }
};
vector<State> st(2 * 100005);
int sz = 1;
int last = 0;
void extendSAM(char ch) {
    int c = ch - 'a';
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    int p = last;
    while (p != -1 && st[p].next[c] == -1) {
        st[p].next[c] = cur;
        p = st[p].link;
    }
    if (p == -1) {
        st[cur].link = 0;
    }
    else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        }
        else {
            int clone = sz++;
            st[clone] = st[q];
            st[clone].len = st[p].len + 1;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}
void buildSAM(string s) {
    st[0] = State();
    st[0].link = -1;
    for (char c : s)
        extendSAM(c);
}
Time Complexity: O(n × alphabet); with fixed alphabet, O(n).

long long countDistinctSubstringsSAM() {
    long long ans = 0;
    for (int v = 1; v < sz; v++) {
        ans += st[v].len - st[st[v].link].len;
    }
    return ans;
}
Time Complexity: O(n).

bool isPeriodic(string s) {
    int n = s.size();
    vector<int> lps(n);
    for (int i = 1, len = 0; i < n; ) {
        if (s[i] == s[len]) {
            lps[i++] = ++len;
        }
        else if (len) {
            len = lps[len - 1];
        }
        else {
            lps[i++] = 0;
        }
    }
    int period = n - lps[n - 1];
    return lps[n - 1] > 0 && n % period == 0;
}
Time Complexity: O(n).

string minimumRotation(string s) {
    string t = s + s;
    int n = s.size();
    int i = 0, j = 1, k = 0;
    while (i < n && j < n && k < n) {
        if (t[i + k] == t[j + k]) {
            k++;
            continue;
        }
        if (t[i + k] > t[j + k])
            i = i + k + 1;
        else
            j = j + k + 1;
        if (i == j)
            j++;
        k = 0;
    }
    int start = min(i, j);
    return t.substr(start, n);
}
Time Complexity: O(n).

class RollingHash {
    static const long long MOD = 1000000007;
    static const long long BASE = 911382323;
    vector<long long> h, power;
public:
    RollingHash(string s) {
        int n = s.size();
        h.resize(n + 1);
        power.resize(n + 1);
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            h[i + 1] =
                (h[i] * BASE + s[i]) % MOD;
            power[i + 1] =
                power[i] * BASE % MOD;
        }
    }
    long long getHash(int l, int r) {
        return (
            h[r + 1] -
            h[l] * power[r - l + 1] % MOD
            + MOD
        ) % MOD;
    }
};
Time Complexity: Preprocessing O(n), substring hash query O(1).

struct Node {
    int next[26];
    int len;
    int link;
    Node(int l = 0) {
        memset(next, 0, sizeof(next));
