        link = 0;
    }
};
vector<Node> tree;
string s;
int suff;
void init() {
    tree.clear();
    tree.push_back(Node(-1)); // node 0
    tree.push_back(Node(0));  // node 1
    tree[0].link = 0;
    tree[1].link = 0;
    suff = 1;
}
int getLink(int v, int pos) {
    while (true) {
        int left = pos - 1 - tree[v].len;
        if (left >= 0 && s[left] == s[pos])
            return v;
        v = tree[v].link;
    }
}
void addChar(char c) {
    s += c;
    int pos = s.size() - 1;
    int cur = getLink(suff, pos);
    int x = c - 'a';
    if (!tree[cur].next[x]) {
        int newNode = tree.size();
        tree.push_back(Node(tree[cur].len + 2));
        if (tree[newNode].len == 1) {
            tree[newNode].link = 1;
        }
        else {
            int linkNode =
                getLink(tree[cur].link, pos);
            tree[newNode].link =
                tree[linkNode].next[x];
        }
        tree[cur].next[x] = newNode;
    }
    suff = tree[cur].next[x];
}
Time Complexity: O(n).

vector<string> duval(string s) {
    int n = s.size();
    vector<string> factorization;
    int i = 0;
    while (i < n) {
        int j = i + 1;
        int k = i;
        while (j < n && s[k] <= s[j]) {
            if (s[k] < s[j])
                k = i;
            else
                k++;
            j++;
        }
        while (i <= k) {
            factorization.push_back(
                s.substr(i, j - k)
            );
            i += j - k;
        }
    }
    return factorization;
}
Time Complexity: O(n).

int longestCommonSubstring(string t) {
