    for (char c : t) {
        int x = c - 'a';
        if (st[v].next[x] != -1) {
            v = st[v].next[x];
            len++;
        }
        else {
            while (v != -1 &&
                   st[v].next[x] == -1) {
                v = st[v].link;
            }
            if (v == -1) {
                v = 0;
                len = 0;
            }
            else {
                len = st[v].len + 1;
                v = st[v].next[x];
            }
        }
        ans = max(ans, len);
    }
    return ans;
}
