class SegmentTree {
    vector<long long> tree, lazy;
    vector<bool> hasLazy;
    int n;
public:
    SegmentTree(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        lazy.resize(4 * n);
        hasLazy.resize(4 * n, false);
        build(arr, 1, 0, n - 1);
    }
    void build(vector<int>& arr, int node, int l, int r) {
        if (l == r) {
            tree[node] = arr[l];
            return;
        }
        int mid = (l + r) / 2;
        build(arr, node * 2, l, mid);
        build(arr, node * 2 + 1, mid + 1, r);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }
    void apply(int node, int l, int r, long long val) {
        tree[node] = (r - l + 1) * val;
        lazy[node] = val;
        hasLazy[node] = true;
    }
    void push(int node, int l, int r) {
        if (!hasLazy[node] || l == r)
            return;
        int mid = (l + r) / 2;
        apply(node * 2, l, mid, lazy[node]);
        apply(node * 2 + 1, mid + 1, r, lazy[node]);
        hasLazy[node] = false;
    }
    void update(int node, int l, int r,
                int ql, int qr, long long val) {
        if (qr < l || r < ql)
            return;
        if (ql <= l && r <= qr) {
            apply(node, l, r, val);
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        update(node * 2, l, mid, ql, qr, val);
        update(node * 2 + 1, mid + 1, r, ql, qr, val);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }
    long long query(int node, int l, int r,
                    int ql, int qr) {
        if (qr < l || r < ql)
            return 0;
        if (ql <= l && r <= qr)
            return tree[node];
        push(node, l, r);
        int mid = (l + r) / 2;
        return query(node * 2, l, mid, ql, qr) +
               query(node * 2 + 1, mid + 1, r, ql, qr);
    }
    void update(int l, int r, long long val) {
        update(1, 0, n - 1, l, r, val);
    }
    long long query(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }
};
Time Complexity: Build O(N), range assignment O(log N), range sum O(log N), space O(N).

void update(int node, int l, int r,
            int ql, int qr, long long val) {
    if (qr < l || r < ql)
        return;
    if (ql <= l && r <= qr) {
        tree[node] += val;
        lazy[node] += val;
        return;
    }
    push(node);
    int mid = (l + r) / 2;
    update(node * 2, l, mid, ql, qr, val);
    update(node * 2 + 1, mid + 1, r, ql, qr, val);
    tree[node] = min(tree[node * 2],
                     tree[node * 2 + 1]);
}
long long query(int node, int l, int r,
                int ql, int qr) {
    if (qr < l || r < ql)
        return LLONG_MAX;
    if (ql <= l && r <= qr)
        return tree[node];
    push(node);
    int mid = (l + r) / 2;
    return min(query(node * 2, l, mid, ql, qr),
               query(node * 2 + 1, mid + 1, r, ql, qr));
}
Time Complexity: Range update O(log N), range minimum query O(log N), space O(N).

void apply(int node, int l, int r,
           long long mul, long long add) {
    tree[node] = tree[node] * mul
               + (r - l + 1) * add;
    lazyMul[node] *= mul;
    lazyAdd[node] = lazyAdd[node] * mul + add;
}
void push(int node, int l, int r) {
    if (l == r)
        return;
    int mid = (l + r) / 2;
    apply(node * 2, l, mid,
          lazyMul[node], lazyAdd[node]);
    apply(node * 2 + 1, mid + 1, r,
          lazyMul[node], lazyAdd[node]);
    lazyMul[node] = 1;
    lazyAdd[node] = 0;
}
