void update(Node*& node, long long l,
            long long r, long long idx,
            long long val) {
    if (!node)
        node = new Node();
    if (l == r) {
        node->sum += val;
        return;
    }
    long long mid = l + (r - l) / 2;
    if (idx <= mid)
        update(node->left, l, mid, idx, val);
    else
        update(node->right, mid + 1, r, idx, val);
    node->sum = 0;
    if (node->left)
        node->sum += node->left->sum;
    if (node->right)
        node->sum += node->right->sum;
}
