struct Node {
    int left, right;
    long long sum;
    Node(int l = 0, int r = 0, long long s = 0)
        : left(l), right(r), sum(s) {}
};
vector<Node> tree;
int update(int oldNode, int l, int r,
           int idx, int val) {
    int newNode = tree.size();
    tree.push_back(tree[oldNode]);
    if (l == r) {
        tree[newNode].sum = val;
        return newNode;
    }
    int mid = (l + r) / 2;
    if (idx <= mid)
        tree[newNode].left =
            update(tree[oldNode].left, l, mid, idx, val);
    else
        tree[newNode].right =
            update(tree[oldNode].right, mid + 1, r, idx, val);
    tree[newNode].sum =
        tree[tree[newNode].left].sum +
        tree[tree[newNode].right].sum;
    return newNode;
}

int kth(int leftRoot, int rightRoot,
        int l, int r, int k) {
    if (l == r)
        return l;
    int mid = (l + r) / 2;
    int leftCount =
        tree[tree[rightRoot].left].sum -
        tree[tree[leftRoot].left].sum;
    if (k <= leftCount) {
        return kth(tree[leftRoot].left,
                   tree[rightRoot].left,
                   l, mid, k);
    }
    return kth(tree[leftRoot].right,
               tree[rightRoot].right,
               mid + 1, r,
               k - leftCount);
}
Time Complexity: Build O(N log N), kth query O(log N), space O(N log N).

vector<vector<int>> tree;
