int dfs(int u, int t, int flow) {
    if (u == t)
        return flow;
    visited[u] = true;
    for (int v = 0; v < n; v++) {
        if (!visited[v] && capacity[u][v] > 0) {
            int pushed = dfs(
                v, t,
                min(flow, capacity[u][v])
            );
            if (pushed > 0) {
                capacity[u][v] -= pushed;
                capacity[v][u] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}
int maxFlow(int s, int t) {
    int flow = 0;
    while (true) {
        fill(visited.begin(),
             visited.end(), false);
        int pushed = dfs(s, t, INT_MAX);
        if (pushed == 0)
            break;
        flow += pushed;
    }
    return flow;
}
Time Complexity: O(E * F) where F is the maximum flow value.

int maxFlow(int s, int t) {
    int flow = 0;
    while (true) {
        vector<int> parent(n, -1);
        queue<int> q;
        q.push(s);
        parent[s] = s;
        while (!q.empty() && parent[t] == -1) {
            int u = q.front();
            q.pop();
            for (int v = 0; v < n; v++) {
                if (parent[v] == -1 &&
                    capacity[u][v] > 0) {
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        if (parent[t] == -1)
            break;
        int pushed = INT_MAX;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            pushed = min(pushed, capacity[u][v]);
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            capacity[u][v] -= pushed;
            capacity[v][u] += pushed;
        }
        flow += pushed;
    }
    return flow;
}
Time Complexity: O(VE²).

struct Edge {
    int to, rev, cap;
};
vector<vector<Edge>> graph;
vector<int> level, ptr;
void addEdge(int u, int v, int cap) {
    Edge a{v, (int)graph[v].size(), cap};
    Edge b{u, (int)graph[u].size(), 0};
    graph[u].push_back(a);
    graph[v].push_back(b);
}
bool bfs(int s, int t) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(s);
    level[s] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto &e : graph[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}
int dfs(int u, int t, int pushed) {
    if (u == t)
        return pushed;
    for (int &cid = ptr[u];
         cid < graph[u].size();
         cid++) {
        Edge &e = graph[u][cid];
        if (e.cap <= 0 ||
            level[e.to] != level[u] + 1)
            continue;
        int tr = dfs(
            e.to,
            t,
            min(pushed, e.cap)
        );
        if (tr == 0)
            continue;
        e.cap -= tr;
