bool bfs() {
    queue<int> q;
    for (int u = 0; u < L; u++) {
        if (pairU[u] == -1) {
            dist[u] = 0;
            q.push(u);
        } else {
            dist[u] = INF;
        }
    }
    bool found = false;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            int nxt = pairV[v];
            if (nxt == -1) {
                found = true;
            }
            else if (dist[nxt] == INF) {
                dist[nxt] = dist[u] + 1;
                q.push(nxt);
            }
        }
    }
    return found;
}
bool dfs(int u) {
    for (int v : adj[u]) {
        int nxt = pairV[v];
        if (nxt == -1 ||
            (dist[nxt] == dist[u] + 1 &&
             dfs(nxt))) {
            pairU[u] = v;
            pairV[v] = u;
            return true;
        }
    }
    dist[u] = INF;
    return false;
}
