int minCostMaxFlow(int s, int t) {
    int flow = 0;
    int cost = 0;
    while (true) {
        vector<int> dist(n, INF);
        vector<int> parentV(n, -1);
        vector<int> parentE(n, -1);
        queue<int> q;
        vector<bool> inQueue(n, false);
        dist[s] = 0;
        q.push(s);
        inQueue[s] = true;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inQueue[u] = false;
            for (int i = 0; i < graph[u].size(); i++) {
                Edge &e = graph[u][i];
                if (e.cap > 0 &&
                    dist[e.to] >
                    dist[u] + e.cost) {
                    dist[e.to] =
                        dist[u] + e.cost;
                    parentV[e.to] = u;
                    parentE[e.to] = i;
                    if (!inQueue[e.to]) {
                        q.push(e.to);
                        inQueue[e.to] = true;
                    }
                }
            }
        }
        if (dist[t] == INF)
            break;
        int pushed = INF;
        for (int v = t; v != s; v = parentV[v]) {
            int u = parentV[v];
            pushed = min(
                pushed,
                graph[u][parentE[v]].cap
            );
        }
        for (int v = t; v != s; v = parentV[v]) {
            int u = parentV[v];
            Edge &e = graph[u][parentE[v]];
            e.cap -= pushed;
            graph[v][e.rev].cap += pushed;
        }
        flow += pushed;
        cost += pushed * dist[t];
    }
    return cost;
}

