bool subsetSumMITM(vector<long long>& arr, long long target) {
    int n = arr.size();
    int mid = n / 2;
    vector<long long> left, right;
    int n1 = mid;
    int n2 = n - mid;
    for (int mask = 0; mask < (1 << n1); mask++) {
        long long sum = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i))
                sum += arr[i];
        }
        left.push_back(sum);
    }
    for (int mask = 0; mask < (1 << n2); mask++) {
        long long sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i))
                sum += arr[mid + i];
        }
        right.push_back(sum);
    }
    sort(right.begin(), right.end());
    for (long long x : left) {
        long long need = target - x;
        if (binary_search(right.begin(), right.end(), need))
            return true;
    }
    return false;
}

long long closestSubsetSum(vector<long long>& arr, long long target) {
    int n = arr.size();
    int mid = n / 2;
    vector<long long> left, right;
    for (int mask = 0; mask < (1 << mid); mask++) {
        long long sum = 0;
        for (int i = 0; i < mid; i++) {
            if (mask & (1 << i))
                sum += arr[i];
        }
        left.push_back(sum);
    }
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        long long sum = 0;
        for (int i = 0; i < rightN; i++) {
            if (mask & (1 << i))
                sum += arr[mid + i];
        }
        right.push_back(sum);
    }
    sort(right.begin(), right.end());
    long long ans = LLONG_MAX;
    for (long long x : left) {
        long long need = target - x;
        auto it = lower_bound(right.begin(), right.end(), need);
        if (it != right.end())
            ans = min(ans, abs(x + *it - target));
        if (it != right.begin()) {
            --it;
            ans = min(ans, abs(x + *it - target));
        }
    }
    return ans;
}

long long countSubsetsLE(vector<long long>& arr, long long X) {
