class Board {
    int n;
    vector<vector<Symbol>> grid;
public:
    Board(int n) : n(n) {
        grid.resize(n, vector<Symbol>(n, Symbol::EMPTY));
    }
    bool makeMove(int r, int c, Symbol symbol) {
        if (r < 0 || r >= n ||
            c < 0 || c >= n ||
            grid[r][c] != Symbol::EMPTY)
            return false;
        grid[r][c] = symbol;
        return true;
    }
    bool isFull() {
        for (auto &row : grid)
            for (auto x : row)
                if (x == Symbol::EMPTY)
                    return false;
        return true;
    }
    bool hasWon(int r, int c, Symbol symbol) {
        // Check row
        bool ok = true;
        for (int j = 0; j < n; j++)
            if (grid[r][j] != symbol)
                ok = false;
        if (ok) return true;
        // Check column
        ok = true;
        for (int i = 0; i < n; i++)
            if (grid[i][c] != symbol)
                ok = false;
        if (ok) return true;
        // Main diagonal
        if (r == c) {
            ok = true;
            for (int i = 0; i < n; i++)
                if (grid[i][i] != symbol)
                    ok = false;
            if (ok) return true;
        }
        // Other diagonal
        if (r + c == n - 1) {
            ok = true;
            for (int i = 0; i < n; i++)
                if (grid[i][n - 1 - i] != symbol)
                    ok = false;
            if (ok) return true;
        }
        return false;
    }
};

class Game {
    Board board;
    Player p1;
    Player p2;
    Player* current;
    GameState state;
public:
    Game(int n, Player p1, Player p2)
        : board(n),
          p1(p1),
          p2(p2),
          current(&this->p1),
          state(GameState::IN_PROGRESS) {}
    void makeMove(int r, int c) {
        if (state != GameState::IN_PROGRESS)
            return;
        if (!board.makeMove(r, c, current->getSymbol()))
            return;
        if (board.hasWon(r, c, current->getSymbol())) {
            state = current->getSymbol() == Symbol::X
                    ? GameState::X_WON
                    : GameState::O_WON;
            return;
        }
        if (board.isFull()) {
            state = GameState::DRAW;
            return;
        }
        current = (current == &p1) ? &p2 : &p1;
    }
};

