class Elevator {
    int id;
    int currentFloor;
    Direction direction;
    ElevatorState state;
    set<int> destinations;
public:
    Elevator(int id)
        : id(id),
          currentFloor(0),
          direction(Direction::IDLE),
          state(ElevatorState::STOPPED) {}
    int getCurrentFloor() {
        return currentFloor;
    }
    Direction getDirection() {
        return direction;
    }
    void addDestination(int floor) {
        destinations.insert(floor);
    }
    void move() {
        if (destinations.empty()) {
            direction = Direction::IDLE;
            return;
        }
        int destination = *destinations.begin();
        if (currentFloor < destination) {
            direction = Direction::UP;
            currentFloor++;
        }
        else if (currentFloor > destination) {
            direction = Direction::DOWN;
            currentFloor--;
        }
        if (currentFloor == destination) {
            destinations.erase(destination);
            openDoor();
        }
    }
    void openDoor() {
        state = ElevatorState::DOOR_OPEN;
        cout << "Elevator " << id
             << " door opened\n";
        state = ElevatorState::STOPPED;
    }
};

class ElevatorController {
    vector<Elevator*> elevators;
public:
    void addElevator(Elevator* e) {
        elevators.push_back(e);
    }
    Elevator* selectElevator(int floor) {
        Elevator* best = nullptr;
        int minDistance = INT_MAX;
        for (auto e : elevators) {
            if (e->getDirection() == Direction::IDLE) {
                int distance =
                    abs(e->getCurrentFloor() - floor);
                if (distance < minDistance) {
                    minDistance = distance;
                    best = e;
                }
            }
        }
        return best;
    }
    void requestElevator(int floor) {
        Elevator* e = selectElevator(floor);
        if (e)
            e->addDestination(floor);
    }
};

