class Directory : public FileSystemNode {
    vector<FileSystemNode*> children;
public:
    Directory(string name)
        : FileSystemNode(name) {}
    void add(FileSystemNode* node) {
        children.push_back(node);
    }
    void remove(FileSystemNode* node) {
        children.erase(
            remove(children.begin(), children.end(), node),
            children.end()
        );
    }
    void ls() override {
        cout << name << "/\n";
        for (auto child : children)
            child->ls();
    }
    int getSize() override {
        int total = 0;
        for (auto child : children)
            total += child->getSize();
        return total;
    }
};

