class BookingSystem {
    int bookingId = 1;
public:
    Booking* book(
        User* user,
        Show* show,
        vector<int> seats
    ) {
        // Check all seats first
        for (int seat : seats) {
            if (!show->isAvailable(seat))
                return nullptr;
        }
        // Reserve all seats
        for (int seat : seats)
            show->bookSeat(seat);
        return new Booking(
            bookingId++,
            user,
            show,
            seats
        );
    }
};

