class DriverMatchingStrategy {
public:
    virtual Driver* findDriver(
        Location source,
        vector<Driver*>& drivers
    ) = 0;
    virtual ~DriverMatchingStrategy() {}
};

class NearestDriverStrategy
    : public DriverMatchingStrategy {
public:
    Driver* findDriver(
        Location source,
        vector<Driver*>& drivers
    ) override {
        Driver* best = nullptr;
        double minDistance = DBL_MAX;
        for (auto driver : drivers) {
            if (!driver->isAvailable())
                continue;
            double distance =
                abs(driver->getLocation().getLatitude()
                    - source.getLatitude())
                +
                abs(driver->getLocation().getLongitude()
                    - source.getLongitude());
            if (distance < minDistance) {
                minDistance = distance;
                best = driver;
            }
        }
        return best;
    }
};

