class PaymentService {
    unordered_map<string, Payment*> payments;
public:
    Payment* makePayment(
        string id,
        string idempotencyKey,
        double amount,
        PaymentProcessor* processor
    ) {
        // Idempotency check
        if (payments.count(idempotencyKey)) {
            return payments[idempotencyKey];
        }
        Payment* payment =
            new Payment(
                id,
                idempotencyKey,
                amount
            );
        payments[idempotencyKey] = payment;
        payment->setStatus(
            PaymentStatus::PROCESSING
        );
        bool success =
            processor->process(amount);
        if (success) {
            payment->setStatus(
                PaymentStatus::SUCCESS
            );
        }
        else {
            payment->setStatus(
                PaymentStatus::FAILED
            );
        }
        return payment;
    }
};

void refund(
    Payment* payment,
    PaymentProcessor* processor
) {
    if (payment->getStatus()
        != PaymentStatus::SUCCESS) {
        return;
    }
    bool success =
        processor->refund(
            payment->getAmount()
        );
    if (success) {
        payment->setStatus(
            PaymentStatus::REFUNDED
        );
    }
}

