class RateLimitStrategy {
public:
    virtual bool allow(string clientId) = 0;
    virtual ~RateLimitStrategy() {}
};

class FixedWindowStrategy : public RateLimitStrategy {
    int limit;
    int windowSize;
    unordered_map<string, int> count;
    unordered_map<string, time_t> windowStart;
public:
    FixedWindowStrategy(int limit, int windowSize)
        : limit(limit), windowSize(windowSize) {}
    bool allow(string clientId) override {
        time_t now = time(nullptr);
        if (!windowStart.count(clientId) ||
            now - windowStart[clientId] >= windowSize) {
            windowStart[clientId] = now;
            count[clientId] = 0;
        }
        if (count[clientId] >= limit)
            return false;
        count[clientId]++;
        return true;
    }
};

class RateLimiter {
    RateLimitStrategy* strategy;
public:
    RateLimiter(RateLimitStrategy* strategy)
        : strategy(strategy) {}
    bool allow(string clientId) {
        return strategy->allow(clientId);
    }
};

