class TaskQueue {
    priority_queue<
        pair<int, Task*>,
        vector<pair<int, Task*>>,
        greater<pair<int, Task*>>
    > pq;
public:
    void addTask(Task* task) {
        pq.push({
            task->getExecutionTime(),
            task
        });
    }
    Task* getNextTask(int currentTime) {
        if (pq.empty())
            return nullptr;
        if (pq.top().first > currentTime)
            return nullptr;
        Task* task = pq.top().second;
        pq.pop();
        return task;
    }
};

class TaskExecutor {
public:
    void execute(Task* task) {
        task->setStatus(TaskStatus::RUNNING);
        cout << "Executing task "
             << task->getId() << "\n";
        // actual task execution
        task->setStatus(TaskStatus::COMPLETED);
    }
};

class Scheduler {
    TaskQueue queue;
    TaskExecutor executor;
public:
    void schedule(Task* task) {
        task->setStatus(TaskStatus::SCHEDULED);
        queue.addTask(task);
    }
    void run(int currentTime) {
        Task* task;
        while ((task = queue.getNextTask(currentTime))) {
            executor.execute(task);
        }
    }
};
